setEmbeddedPersistenceBundle(JSON.parse("{\"queries\":{\"store.sql\":\"-- Storefront read queries. Application queries use the checked query boundary;\\n-- templates and handlers never issue raw SQL.\\n\\n-- name: GetStore :one\\nSELECT CAST(id AS TEXT) AS id, name, currency_code, CAST(currency_exponent AS TEXT) AS currency_exponent\\nFROM store\\nWHERE id = 1;\\n\",\"cart.sql\":\"-- Anonymous sessions and their single cart. Sessions are identified only by\\n-- the SHA-256 digest of a server-generated bearer token; expiry is checked\\n-- on every lookup. Cart prices are never stored: reads join current catalog\\n-- rows so price, publication, and availability are always current.\\n\\n-- name: GetLiveSession :one\\nSELECT token_hash\\nFROM sessions\\nWHERE token_hash = ? AND expires_at > CAST(? AS INTEGER);\\n\\n-- name: InsertSession :exec\\nINSERT INTO sessions (token_hash, created_at, expires_at)\\nVALUES (?, CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: DeleteExpiredSessions :execrows\\nDELETE FROM sessions\\nWHERE token_hash IN (\\n  SELECT e.token_hash FROM sessions e\\n  WHERE e.expires_at <= CAST(? AS INTEGER)\\n  ORDER BY e.expires_at\\n  LIMIT CAST(? AS INTEGER)\\n);\\n\\n-- name: GetVariantForCart :one\\nSELECT CAST(v.id AS TEXT) AS id, CAST(CASE WHEN v.available = 1 AND NOT EXISTS (SELECT 1 FROM inventory_levels i WHERE i.variant_id = v.id AND i.on_hand - i.held - i.allocated <= 0) THEN 1 ELSE 0 END AS TEXT) AS available, p.status AS product_status\\nFROM product_variants v\\nJOIN products p ON p.id = v.product_id\\nWHERE v.id = CAST(? AS INTEGER);\\n\\n-- name: GetCartQuantity :one\\nSELECT CAST(quantity AS TEXT) AS quantity\\nFROM cart_items\\nWHERE session_hash = ? AND variant_id = CAST(? AS INTEGER);\\n\\n-- name: CountCartLines :one\\nSELECT CAST(COUNT(*) AS TEXT) AS \\\"COUNT(*)\\\"\\nFROM cart_items\\nWHERE session_hash = ?;\\n\\n-- name: UpsertCartItem :exec\\nINSERT INTO cart_items (session_hash, variant_id, quantity, added_at)\\nVALUES (?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT (session_hash, variant_id) DO UPDATE SET quantity = excluded.quantity;\\n\\n-- name: DeleteCartItem :execrows\\nDELETE FROM cart_items\\nWHERE session_hash = ? AND variant_id = CAST(? AS INTEGER);\\n\\n-- name: ListCartLines :many\\nSELECT CAST(c.variant_id AS TEXT) AS variant_id, CAST(c.quantity AS TEXT) AS quantity,\\n  v.title AS variant_title, CAST(v.price_minor AS TEXT) AS price_minor,\\n  CAST(CASE WHEN v.available = 1 AND NOT EXISTS (SELECT 1 FROM inventory_levels i WHERE i.variant_id = v.id AND i.on_hand - i.held - i.allocated <= 0) THEN 1 ELSE 0 END AS TEXT) AS available, p.handle, p.title AS product_title, p.status AS product_status,\\n  COALESCE(cp.path, m.url) AS image_url, m.alt_text AS image_alt,\\n  CAST(COALESCE(cm.width, m.width) AS TEXT) AS image_width,\\n  CAST(COALESCE(cm.height, m.height) AS TEXT) AS image_height\\nFROM cart_items c\\nJOIN product_variants v ON v.id = c.variant_id\\nJOIN products p ON p.id = v.product_id\\nLEFT JOIN product_images m ON m.product_id = p.id AND m.position = (\\n  SELECT MIN(position) FROM product_images WHERE product_id = p.id)\\nLEFT JOIN media_assets dm ON dm.id = m.media_id\\nLEFT JOIN media_assets cm ON cm.id = dm.card_id\\nLEFT JOIN media_public_paths cp ON cp.media_id = cm.id\\nWHERE c.session_hash = ?\\nORDER BY c.added_at ASC, c.variant_id ASC;\\n\\n-- name: ListVariantSelectionLabels :many\\nSELECT CAST(s.variant_id AS TEXT) AS variant_id, ov.value\\nFROM cart_items c\\nJOIN variant_option_values s ON s.variant_id = c.variant_id\\nJOIN product_options o ON o.id = s.option_id\\nJOIN product_option_values ov ON ov.id = s.option_value_id\\nWHERE c.session_hash = ?\\nORDER BY s.variant_id ASC, o.position ASC;\\n\",\"catalog_read.sql\":\"-- Public catalog reads use an immutable in-memory snapshot. These queries\\n-- load active products and collections in one read transaction; catalog\\n-- generation indicates when to rebuild the snapshot. Carts read current\\n-- rows, while snapshot order stays stable because each ORDER BY ends in a\\n-- unique key.\\n\\n-- name: GetCatalogVersions :one\\nSELECT CAST(c.generation AS TEXT) AS generation, CAST(s.version AS TEXT) AS stock_version\\nFROM catalog_state c, stock_state s\\nWHERE c.id = 1 AND s.id = 1;\\n\\n-- name: GetCatalogGeneration :one\\nSELECT CAST(generation AS TEXT) AS generation\\nFROM catalog_state\\nWHERE id = 1;\\n\\n-- Preflight the published snapshot inside the same read transaction before\\n-- the query boundary materializes any of its row slices. Counts bound row and derived-index\\n-- work; text bytes bound variable-size fields missed by row counts.\\n-- name: GetPublishedCatalogFootprint :one\\nSELECT\\n  CAST((SELECT count(*) FROM products WHERE status = 'active') AS TEXT) AS products,\\n  CAST((SELECT count(*) FROM product_variants v JOIN products p ON p.id = v.product_id WHERE p.status = 'active') AS TEXT) AS variants,\\n  CAST((SELECT count(*) FROM variant_option_values s JOIN products p ON p.id = s.product_id WHERE p.status = 'active') AS TEXT) AS selections,\\n  CAST((SELECT count(*) FROM product_option_values ov JOIN product_options o ON o.id = ov.option_id JOIN products p ON p.id = o.product_id WHERE p.status = 'active') AS TEXT) AS option_values,\\n  CAST((SELECT count(*) FROM product_images i JOIN products p ON p.id = i.product_id WHERE p.status = 'active') AS TEXT) AS images,\\n  CAST((SELECT count(*) FROM product_details d JOIN products p ON p.id = d.product_id WHERE p.status = 'active') AS TEXT) AS details,\\n  CAST((SELECT count(*) FROM collections WHERE status = 'active') AS TEXT) AS collections,\\n  CAST((SELECT count(*) FROM collection_products cp JOIN collections c ON c.id = cp.collection_id JOIN products p ON p.id = cp.product_id WHERE c.status = 'active' AND p.status = 'active') AS TEXT) AS members,\\n  CAST(\\n    (SELECT coalesce(sum(length(cast(handle AS blob)) + length(cast(title AS blob)) + length(cast(coalesce(vendor, '') AS blob)) + length(cast(description AS blob))), 0) FROM products WHERE status = 'active')\\n    + (SELECT coalesce(sum(length(cast(coalesce(v.title, '') AS blob))), 0) FROM product_variants v JOIN products p ON p.id = v.product_id WHERE p.status = 'active')\\n    + (SELECT coalesce(sum(length(cast(o.name AS blob)) + length(cast(ov.value AS blob))), 0) FROM product_option_values ov JOIN product_options o ON o.id = ov.option_id JOIN products p ON p.id = o.product_id WHERE p.status = 'active')\\n    + (SELECT coalesce(sum(length(cast(i.url AS blob)) + length(cast(i.alt_text AS blob))), 0) FROM product_images i JOIN products p ON p.id = i.product_id WHERE p.status = 'active')\\n    + (SELECT coalesce(sum(length(cast(d.key AS blob)) + length(cast(d.title AS blob)) + length(cast(d.body AS blob))), 0) FROM product_details d JOIN products p ON p.id = d.product_id WHERE p.status = 'active')\\n    + (SELECT coalesce(sum(length(cast(handle AS blob)) + length(cast(title AS blob)) + length(cast(description AS blob))), 0) FROM collections WHERE status = 'active')\\n  AS TEXT) AS text_bytes;\\n\\n-- Handle order is the \\\"featured\\\" order of the global listing.\\n-- name: ListPublishedProducts :many\\nSELECT CAST(p.id AS TEXT) AS id, p.handle, p.title, p.vendor, p.description\\nFROM products p\\nWHERE p.status = 'active'\\nORDER BY p.handle ASC;\\n\\n-- name: ListPublishedVariants :many\\nSELECT CAST(v.product_id AS TEXT) AS product_id, CAST(v.id AS TEXT) AS id, v.title,\\n  CAST(v.price_minor AS TEXT) AS price_minor, CAST(CASE WHEN v.available = 1 AND NOT EXISTS (SELECT 1 FROM inventory_levels i WHERE i.variant_id = v.id AND i.on_hand - i.held - i.allocated <= 0) THEN 1 ELSE 0 END AS TEXT) AS available\\nFROM product_variants v\\nJOIN products p ON p.id = v.product_id\\nWHERE p.status = 'active'\\nORDER BY v.product_id ASC, v.position ASC, v.id ASC;\\n\\n-- Each variant's selected values, in option order.\\n-- name: ListPublishedSelections :many\\nSELECT CAST(s.variant_id AS TEXT) AS variant_id, CAST(s.option_value_id AS TEXT) AS option_value_id\\nFROM variant_option_values s\\nJOIN product_options o ON o.id = s.option_id\\nJOIN products p ON p.id = s.product_id\\nWHERE p.status = 'active'\\nORDER BY s.variant_id ASC, o.position ASC;\\n\\n-- name: ListPublishedOptionValues :many\\nSELECT CAST(o.product_id AS TEXT) AS product_id, CAST(o.id AS TEXT) AS option_id, o.name AS option_name,\\n  CAST(ov.id AS TEXT) AS value_id, ov.value\\nFROM product_options o\\nJOIN product_option_values ov ON ov.option_id = o.id\\nJOIN products p ON p.id = o.product_id\\nWHERE p.status = 'active'\\nORDER BY o.product_id ASC, o.position ASC, o.id ASC, ov.position ASC, ov.id ASC;\\n\\n-- name: ListPublishedImages :many\\nSELECT CAST(m.product_id AS TEXT) AS product_id, m.url, m.alt_text,\\n  CAST(m.width AS TEXT) AS width, CAST(m.height AS TEXT) AS height,\\n  cp.path AS card_url, CAST(cm.width AS TEXT) AS card_width, CAST(cm.height AS TEXT) AS card_height\\nFROM product_images m\\nJOIN products p ON p.id = m.product_id\\nLEFT JOIN media_assets dm ON dm.id = m.media_id\\nLEFT JOIN media_assets cm ON cm.id = dm.card_id\\nLEFT JOIN media_public_paths cp ON cp.media_id = cm.id\\nWHERE p.status = 'active'\\nORDER BY m.product_id ASC, m.position ASC, m.id ASC;\\n\\n-- name: ListPublishedDetails :many\\nSELECT CAST(d.product_id AS TEXT) AS product_id, d.key, d.title, d.body\\nFROM product_details d\\nJOIN products p ON p.id = d.product_id\\nWHERE p.status = 'active'\\nORDER BY d.product_id ASC, d.position ASC;\\n\\n-- name: ListPublishedCollections :many\\nSELECT CAST(c.id AS TEXT) AS id, c.handle, c.title, c.description\\nFROM collections c\\nWHERE c.status = 'active'\\nORDER BY c.title ASC, c.id ASC;\\n\\n-- Membership of published products in published collections, in\\n-- collection order.\\n-- name: ListPublishedMembers :many\\nSELECT CAST(cp.collection_id AS TEXT) AS collection_id, CAST(cp.product_id AS TEXT) AS product_id\\nFROM collection_products cp\\nJOIN collections c ON c.id = cp.collection_id\\nJOIN products p ON p.id = cp.product_id\\nWHERE c.status = 'active' AND p.status = 'active'\\nORDER BY cp.collection_id ASC, cp.position ASC;\\n\\n-- name: GetShopProfile :one\\nSELECT description, contact_email, contact_phone FROM shop_profile WHERE id = 1;\\n\\n-- name: ListShopPages :many\\nSELECT kind, blocks FROM shop_pages ORDER BY kind ASC;\\n\\n-- Old handles that still lead to an active resource. A handle that a live\\n-- product or collection holds never redirects.\\n-- name: ListPublishedRedirects :many\\nSELECT r.kind, r.old_handle, r.target_handle\\nFROM handle_redirects r\\nWHERE (r.kind = 'product' AND EXISTS (SELECT 1 FROM products p WHERE p.handle = r.target_handle AND p.status = 'active'))\\n  OR (r.kind = 'collection' AND EXISTS (SELECT 1 FROM collections c WHERE c.handle = r.target_handle AND c.status = 'active'))\\nORDER BY r.kind ASC, r.old_handle ASC\\nLIMIT 5000;\\n\",\"catalog_write.sql\":\"-- Catalog import writes and pre-replacement reads. Imports run in one\\n-- transaction with foreign keys enabled; positions come from fixture array\\n-- order. Deletions rely on ON DELETE CASCADE and touch only the four parent\\n-- tables, which share no foreign keys between them.\\n\\n-- name: CountStore :one\\nSELECT CAST(COUNT(*) AS TEXT) AS \\\"COUNT(*)\\\" FROM store;\\n\\n-- name: CountSessions :one\\nSELECT CAST(COUNT(*) AS TEXT) AS \\\"COUNT(*)\\\" FROM sessions;\\n\\n-- name: CountCartItems :one\\nSELECT CAST(COUNT(*) AS TEXT) AS \\\"COUNT(*)\\\" FROM cart_items;\\n\\n-- The two commercial views are the only place later migrations extend to make\\n-- replacement refuse more records; this query never changes.\\n-- name: CountCommercialRecords :one\\nSELECT CAST((SELECT COUNT(*) FROM commercial_variant_references) AS TEXT) AS variant_references,\\n  CAST((SELECT COUNT(*) FROM currency_bound_rows) AS TEXT) AS bound_rows;\\n\\n-- name: InsertStore :exec\\nINSERT INTO store (id, name, currency_code, currency_exponent)\\nVALUES (1, ?, ?, CAST(? AS INTEGER));\\n\\n-- name: DeleteStore :exec\\nDELETE FROM store;\\n\\n-- name: DeleteAllProducts :exec\\nDELETE FROM products;\\n\\n-- name: DeleteAllCollections :exec\\nDELETE FROM collections;\\n\\n-- name: DeleteAllSessions :exec\\nDELETE FROM sessions;\\n\\n-- name: InsertProduct :exec\\nINSERT INTO products (id, handle, title, vendor, description, status)\\nVALUES (CAST(? AS INTEGER), ?, ?, ?, ?, ?);\\n\\n-- name: InsertProductDetail :exec\\nINSERT INTO product_details (product_id, key, title, body, position)\\nVALUES (CAST(? AS INTEGER), ?, ?, ?, CAST(? AS INTEGER));\\n\\n-- name: InsertProductOption :exec\\nINSERT INTO product_options (id, product_id, name, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, CAST(? AS INTEGER));\\n\\n-- name: InsertProductOptionValue :exec\\nINSERT INTO product_option_values (id, option_id, value, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, CAST(? AS INTEGER));\\n\\n-- name: InsertProductVariant :exec\\nINSERT INTO product_variants (id, product_id, title, price_minor, available, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertVariantOptionValue :exec\\nINSERT INTO variant_option_values (variant_id, product_id, option_id, option_value_id)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertProductImage :exec\\nINSERT INTO product_images (id, product_id, url, alt_text, width, height, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertCollection :exec\\nINSERT INTO collections (id, handle, title, description, status)\\nVALUES (CAST(? AS INTEGER), ?, ?, ?, ?);\\n\\n-- name: InsertCollectionProduct :exec\\nINSERT INTO collection_products (collection_id, product_id, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\",\"catalog_verify.sql\":\"-- Final-transaction-state verification for imports. DDL enforces foreign\\n-- keys, uniqueness, ranges, and text shape; these queries cover the\\n-- application rules DDL cannot express: complete option coverage per\\n-- variant and value coverage per option. The importer checks duplicate\\n-- complete selection tuples against ListVariantSelections after writes.\\n\\n-- name: ProductImportStats :many\\nSELECT CAST(p.id AS TEXT) AS product_id, CAST(COUNT(DISTINCT v.id) AS TEXT) AS variants,\\n  CAST(COUNT(DISTINCT o.id) AS TEXT) AS options\\nFROM products p\\nLEFT JOIN product_variants v ON v.product_id = p.id\\nLEFT JOIN product_options o ON o.product_id = p.id\\nGROUP BY p.id;\\n\\n-- name: OptionImportStats :many\\nSELECT CAST(o.id AS TEXT) AS option_id, CAST(COUNT(ov.id) AS TEXT) AS opt_values\\nFROM product_options o\\nLEFT JOIN product_option_values ov ON ov.option_id = o.id\\nGROUP BY o.id;\\n\\n-- name: VariantImportStats :many\\nSELECT CAST(v.id AS TEXT) AS variant_id, CAST(v.product_id AS TEXT) AS product_id,\\n  CAST(COUNT(s.option_id) AS TEXT) AS selections,\\n  CAST((SELECT COUNT(*) FROM product_options o WHERE o.product_id = v.product_id) AS TEXT) AS options\\nFROM product_variants v\\nLEFT JOIN variant_option_values s ON s.variant_id = v.id\\nGROUP BY v.id;\\n\\n-- name: ListVariantSelections :many\\nSELECT CAST(s.variant_id AS TEXT) AS variant_id, CAST(s.product_id AS TEXT) AS product_id,\\n  CAST(s.option_id AS TEXT) AS option_id, CAST(s.option_value_id AS TEXT) AS option_value_id\\nFROM variant_option_values s\\nORDER BY s.variant_id, s.option_id;\\n\"},\"commerceQueries\":{\"commerce.sql\":\"-- Commerce core queries (docs/commerce.md). int64 columns are projected with\\n-- CAST(col AS TEXT) and bound through CAST(? AS INTEGER), like every query.\\n\\n-- name: GetStockRead :one\\nSELECT CAST(v.id AS TEXT) AS variant_id,\\n  CAST(l.on_hand AS TEXT) AS on_hand, CAST(l.held AS TEXT) AS held,\\n  CAST(l.allocated AS TEXT) AS allocated, CAST(l.revision AS TEXT) AS revision\\nFROM product_variants v\\nLEFT JOIN inventory_levels l ON l.variant_id = v.id\\nWHERE v.id = CAST(? AS INTEGER);\\n\\n-- name: InsertInventoryLevel :exec\\nINSERT INTO inventory_levels (variant_id, on_hand, held, allocated)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: UpdateInventoryLevel :exec\\nUPDATE inventory_levels\\nSET on_hand = CAST(? AS INTEGER), held = CAST(? AS INTEGER), allocated = CAST(? AS INTEGER),\\n  revision = revision + 1\\nWHERE variant_id = CAST(? AS INTEGER);\\n\\n-- name: InsertStockAdjustment :exec\\nINSERT INTO stock_adjustments (variant_id, kind, delta, on_hand_after, reason, actor, created_at)\\nVALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER));\\n\\n-- name: InsertAuditEvent :exec\\nINSERT INTO audit_events (actor, action, entity_kind, entity_id, entity_revision, summary, created_at)\\nVALUES (?, ?, ?, ?, CAST(? AS INTEGER), ?, CAST(? AS INTEGER));\\n\\n-- name: GetStockStateVersion :one\\nSELECT CAST(version AS TEXT) AS version FROM stock_state WHERE id = 1;\\n\\n-- name: ListSoldOutVariants :many\\nSELECT CAST(variant_id AS TEXT) AS variant_id\\nFROM inventory_levels\\nWHERE on_hand - held - allocated <= 0\\nORDER BY variant_id;\\n\\n-- name: ListStockAdjustments :many\\nSELECT CAST(id AS TEXT) AS id, CAST(variant_id AS TEXT) AS variant_id, kind,\\n  CAST(delta AS TEXT) AS delta, CAST(on_hand_after AS TEXT) AS on_hand_after,\\n  reason, actor, CAST(created_at AS TEXT) AS created_at\\nFROM stock_adjustments\\nWHERE variant_id = CAST(? AS INTEGER)\\nORDER BY id;\\n\\n-- name: ListAuditEvents :many\\nSELECT CAST(id AS TEXT) AS id, actor, action, entity_kind, entity_id,\\n  CAST(entity_revision AS TEXT) AS entity_revision, summary, CAST(created_at AS TEXT) AS created_at\\nFROM audit_events\\nWHERE entity_kind = ? AND entity_id = ?\\nORDER BY id;\\n\"},\"adminQueries\":{\"admin.sql\":\"-- Merchant admin sessions, form tokens, and the read models of the admin\\n-- pages. Digests are bound as blobs; int64 columns follow the usual\\n-- CAST(col AS TEXT) and CAST(? AS INTEGER) rule.\\n\\n-- name: GetAdminSession :one\\nSELECT issuer, subject, email, CAST(created_at AS TEXT) AS created_at,\\n  CAST(authenticated_at AS TEXT) AS authenticated_at,\\n  CAST(last_seen_at AS TEXT) AS last_seen_at, CAST(expires_at AS TEXT) AS expires_at\\nFROM admin_sessions\\nWHERE token_digest = ?;\\n\\n-- name: InsertAdminSession :exec\\nINSERT INTO admin_sessions (token_digest, issuer, subject, email, created_at, authenticated_at, last_seen_at, expires_at)\\nVALUES (?, ?, ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: TouchAdminSession :exec\\nUPDATE admin_sessions SET last_seen_at = CAST(? AS INTEGER) WHERE token_digest = ?;\\n\\n-- name: SetAdminSessionAuthentication :execrows\\nUPDATE admin_sessions\\nSET authenticated_at = CAST(? AS INTEGER), last_seen_at = CAST(? AS INTEGER)\\nWHERE token_digest = ? AND issuer = ? AND subject = ?;\\n\\n-- name: DeleteAdminSession :execrows\\nDELETE FROM admin_sessions WHERE token_digest = ?;\\n\\n-- name: DeleteAdminSessionsByPrincipal :execrows\\nDELETE FROM admin_sessions WHERE issuer = ? AND subject = ?;\\n\\n-- name: DeleteAllAdminSessions :execrows\\nDELETE FROM admin_sessions;\\n\\n-- name: DeleteExpiredAdminSessions :execrows\\nDELETE FROM admin_sessions\\nWHERE token_digest IN (\\n  SELECT e.token_digest FROM admin_sessions e\\n  WHERE e.expires_at <= CAST(? AS INTEGER) OR e.last_seen_at <= CAST(? AS INTEGER)\\n  ORDER BY e.expires_at\\n  LIMIT 100\\n);\\n\\n-- name: InsertFormToken :exec\\nINSERT INTO form_tokens (token_digest, session_digest, purpose, created_at, expires_at)\\nVALUES (?, ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: GetFormToken :one\\nSELECT purpose, CAST(expires_at AS TEXT) AS expires_at\\nFROM form_tokens\\nWHERE token_digest = ? AND session_digest = ?;\\n\\n-- name: DeleteFormToken :execrows\\nDELETE FROM form_tokens WHERE token_digest = ?;\\n\\n-- name: DeleteExpiredFormTokens :execrows\\nDELETE FROM form_tokens WHERE session_digest = ? AND expires_at <= CAST(? AS INTEGER);\\n\\n-- name: TrimFormTokens :execrows\\nDELETE FROM form_tokens\\nWHERE session_digest = ? AND token_digest NOT IN (\\n  SELECT t.token_digest FROM form_tokens t\\n  WHERE t.session_digest = ?\\n  ORDER BY t.created_at DESC, t.token_digest\\n  LIMIT 99\\n);\\n\\n-- name: GetStockVariant :one\\nSELECT CAST(v.id AS TEXT) AS variant_id, p.title AS product_title, v.title AS variant_title\\nFROM product_variants v\\nJOIN products p ON p.id = v.product_id\\nWHERE v.id = CAST(? AS INTEGER);\\n\\n-- name: ListRecentStockAdjustments :many\\nSELECT CAST(id AS TEXT) AS id, kind, CAST(delta AS TEXT) AS delta,\\n  CAST(on_hand_after AS TEXT) AS on_hand_after, reason, actor, CAST(created_at AS TEXT) AS created_at\\nFROM stock_adjustments\\nWHERE variant_id = CAST(? AS INTEGER)\\nORDER BY id DESC\\nLIMIT 20;\\n\\n-- name: ListRecentAuditEvents :many\\nSELECT CAST(id AS TEXT) AS id, actor, action, CAST(entity_revision AS TEXT) AS entity_revision,\\n  summary, CAST(created_at AS TEXT) AS created_at\\nFROM audit_events\\nWHERE entity_kind = ? AND entity_id = ?\\nORDER BY id DESC\\nLIMIT 20;\\n\",\"catalog_admin.sql\":\"-- Merchant catalog administration: the read models of the catalog pages and\\n-- the incremental writes behind them. Every int64 projects through\\n-- CAST(col AS TEXT) and binds through CAST(? AS INTEGER). New rows take\\n-- explicit ids from CatalogNextIds, because the Durable Object cursor does\\n-- not report last_insert_rowid.\\n\\n-- name: GetCatalogStore :one\\nSELECT name, currency_code, CAST(currency_exponent AS TEXT) AS currency_exponent FROM store WHERE id = 1;\\n\\n-- name: CatalogNextIds :one\\nSELECT\\n  CAST(COALESCE((SELECT MAX(id) FROM products), 0) + 1 AS TEXT) AS product,\\n  CAST(COALESCE((SELECT MAX(id) FROM collections), 0) + 1 AS TEXT) AS collection,\\n  CAST(COALESCE((SELECT MAX(id) FROM product_options), 0) + 1 AS TEXT) AS option,\\n  CAST(COALESCE((SELECT MAX(id) FROM product_option_values), 0) + 1 AS TEXT) AS value,\\n  CAST(COALESCE((SELECT MAX(id) FROM product_variants), 0) + 1 AS TEXT) AS variant;\\n\\n-- name: CatalogNextPositions :one\\nSELECT\\n  CAST(COALESCE((SELECT MAX(position) FROM product_variants WHERE product_id = CAST(? AS INTEGER)) + 1, 0) AS TEXT) AS variant,\\n  CAST(COALESCE((SELECT MAX(position) FROM product_options WHERE product_id = CAST(? AS INTEGER)) + 1, 0) AS TEXT) AS option;\\n\\n-- name: CatalogNextValuePosition :one\\nSELECT CAST(COALESCE(MAX(position) + 1, 0) AS TEXT) AS position FROM product_option_values WHERE option_id = CAST(? AS INTEGER);\\n\\n-- name: CatalogNextMemberPosition :one\\nSELECT CAST(COALESCE(MAX(position) + 1, 0) AS TEXT) AS position FROM collection_products WHERE collection_id = CAST(? AS INTEGER);\\n\\n-- name: ListCatalogProducts :many\\nSELECT CAST(p.id AS TEXT) AS id, p.handle, p.title, p.status, CAST(p.revision AS TEXT) AS revision,\\n  CAST((SELECT COUNT(*) FROM product_variants v WHERE v.product_id = p.id) AS TEXT) AS variant_count,\\n  CAST((SELECT MIN(v.price_minor) FROM product_variants v WHERE v.product_id = p.id) AS TEXT) AS min_price,\\n  CAST((SELECT MAX(v.price_minor) FROM product_variants v WHERE v.product_id = p.id) AS TEXT) AS max_price\\nFROM products p\\nWHERE p.id > CAST(? AS INTEGER) AND (? = '' OR p.status = ?)\\nORDER BY p.id\\nLIMIT 51;\\n\\n-- name: GetCatalogProduct :one\\nSELECT CAST(id AS TEXT) AS id, handle, title, vendor, description, status, CAST(revision AS TEXT) AS revision\\nFROM products WHERE id = CAST(? AS INTEGER);\\n\\n-- name: FindCatalogProductByHandle :one\\nSELECT CAST(id AS TEXT) AS id FROM products WHERE handle = ?;\\n\\n-- name: CountCatalogProducts :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM products;\\n\\n-- name: ListCatalogProductOptions :many\\nSELECT CAST(id AS TEXT) AS id, name FROM product_options WHERE product_id = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: ListCatalogProductValues :many\\nSELECT CAST(v.id AS TEXT) AS id, CAST(v.option_id AS TEXT) AS option_id, v.value\\nFROM product_option_values v\\nJOIN product_options o ON o.id = v.option_id\\nWHERE o.product_id = CAST(? AS INTEGER)\\nORDER BY o.position, v.position;\\n\\n-- name: ListCatalogProductVariants :many\\nSELECT CAST(v.id AS TEXT) AS id, v.title, CAST(v.price_minor AS TEXT) AS price_minor, CAST(v.available AS TEXT) AS available,\\n  CAST(v.position AS TEXT) AS position,\\n  CAST(l.on_hand AS TEXT) AS on_hand, CAST(l.held AS TEXT) AS held, CAST(l.allocated AS TEXT) AS allocated,\\n  CAST((SELECT COUNT(*) FROM cart_items c WHERE c.variant_id = v.id) AS TEXT) AS cart_lines\\nFROM product_variants v\\nLEFT JOIN inventory_levels l ON l.variant_id = v.id\\nWHERE v.product_id = CAST(? AS INTEGER)\\nORDER BY v.position, v.id;\\n\\n-- name: ListCatalogProductSelections :many\\nSELECT CAST(variant_id AS TEXT) AS variant_id, CAST(option_id AS TEXT) AS option_id, CAST(option_value_id AS TEXT) AS value_id\\nFROM variant_option_values WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: ListCatalogProductImages :many\\nSELECT CAST(id AS TEXT) AS id, url, alt_text, CAST(width AS TEXT) AS width, CAST(height AS TEXT) AS height,\\n  CAST(media_id AS TEXT) AS media_id, CAST(position AS TEXT) AS position\\nFROM product_images WHERE product_id = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: ListCatalogProductDetails :many\\nSELECT key, title, body, CAST(position AS TEXT) AS position\\nFROM product_details WHERE product_id = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: ListCatalogProductCollections :many\\nSELECT CAST(c.id AS TEXT) AS id, c.title, c.status\\nFROM collection_products m\\nJOIN collections c ON c.id = m.collection_id\\nWHERE m.product_id = CAST(? AS INTEGER)\\nORDER BY c.title, c.id\\nLIMIT 50;\\n\\n-- name: CountVariantCartLines :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM cart_items WHERE variant_id = CAST(? AS INTEGER);\\n\\n-- name: CountVariantCommercialReferences :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM commercial_variant_references WHERE variant_id = CAST(? AS INTEGER);\\n\\n-- name: GetCatalogVariant :one\\nSELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id FROM product_variants WHERE id = CAST(? AS INTEGER);\\n\\n-- name: ListCatalogCollections :many\\nSELECT CAST(c.id AS TEXT) AS id, c.handle, c.title, c.status, CAST(c.revision AS TEXT) AS revision,\\n  CAST((SELECT COUNT(*) FROM collection_products m WHERE m.collection_id = c.id) AS TEXT) AS member_count\\nFROM collections c\\nWHERE c.id > CAST(? AS INTEGER)\\nORDER BY c.id\\nLIMIT 51;\\n\\n-- name: GetCatalogCollection :one\\nSELECT CAST(id AS TEXT) AS id, handle, title, description, status, CAST(revision AS TEXT) AS revision\\nFROM collections WHERE id = CAST(? AS INTEGER);\\n\\n-- name: CountCatalogCollections :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM collections;\\n\\n-- name: FindCatalogCollectionByHandle :one\\nSELECT CAST(id AS TEXT) AS id FROM collections WHERE handle = ?;\\n\\n-- name: ListCatalogCollectionMembers :many\\nSELECT CAST(p.id AS TEXT) AS product_id, p.handle, p.title, p.status, CAST(m.position AS TEXT) AS position\\nFROM collection_products m\\nJOIN products p ON p.id = m.product_id\\nWHERE m.collection_id = CAST(? AS INTEGER)\\nORDER BY m.position\\nLIMIT 200;\\n\\n-- name: CountCatalogCollectionMembers :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM collection_products WHERE collection_id = CAST(? AS INTEGER);\\n\\n-- name: GetCatalogMember :one\\nSELECT CAST(product_id AS TEXT) AS product_id, CAST(position AS TEXT) AS position\\nFROM collection_products WHERE collection_id = CAST(? AS INTEGER) AND product_id = CAST(? AS INTEGER);\\n\\n-- name: GetCatalogMemberAbove :one\\nSELECT CAST(product_id AS TEXT) AS product_id, CAST(position AS TEXT) AS position\\nFROM collection_products WHERE collection_id = CAST(? AS INTEGER) AND position < CAST(? AS INTEGER)\\nORDER BY position DESC LIMIT 1;\\n\\n-- name: GetCatalogMemberBelow :one\\nSELECT CAST(product_id AS TEXT) AS product_id, CAST(position AS TEXT) AS position\\nFROM collection_products WHERE collection_id = CAST(? AS INTEGER) AND position > CAST(? AS INTEGER)\\nORDER BY position LIMIT 1;\\n\\n-- name: InsertCatalogProduct :exec\\nINSERT INTO products (id, handle, title, vendor, description, status)\\nVALUES (CAST(? AS INTEGER), ?, ?, ?, ?, ?);\\n\\n-- name: UpdateCatalogProduct :exec\\nUPDATE products SET handle = ?, title = ?, vendor = ?, description = ?, revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: SetCatalogProductStatus :exec\\nUPDATE products SET status = ?, revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: TouchCatalogProduct :exec\\nUPDATE products SET revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: InsertCatalogDetail :exec\\nINSERT INTO product_details (product_id, key, title, body, position)\\nVALUES (CAST(? AS INTEGER), ?, ?, ?, CAST(? AS INTEGER));\\n\\n-- name: InsertCatalogOption :exec\\nINSERT INTO product_options (id, product_id, name, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, CAST(? AS INTEGER));\\n\\n-- name: InsertCatalogOptionValue :exec\\nINSERT INTO product_option_values (id, option_id, value, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, CAST(? AS INTEGER));\\n\\n-- name: InsertCatalogVariant :exec\\nINSERT INTO product_variants (id, product_id, title, price_minor, available, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertCatalogSelection :exec\\nINSERT INTO variant_option_values (variant_id, product_id, option_id, option_value_id)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertCatalogImage :exec\\nINSERT INTO product_images (id, product_id, url, alt_text, width, height, position)\\nVALUES ((SELECT COALESCE(MAX(id), 0) + 1 FROM product_images), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: UpdateCatalogVariant :exec\\nUPDATE product_variants SET title = ?, price_minor = CAST(? AS INTEGER), available = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER);\\n\\n-- name: DeleteCatalogVariant :exec\\nDELETE FROM product_variants WHERE id = CAST(? AS INTEGER);\\n\\n-- name: DeleteCatalogSelectionsOfOption :exec\\nDELETE FROM variant_option_values WHERE option_id = CAST(? AS INTEGER);\\n\\n-- name: DeleteCatalogOption :exec\\nDELETE FROM product_options WHERE id = CAST(? AS INTEGER);\\n\\n-- name: DeleteCatalogOptionValue :exec\\nDELETE FROM product_option_values WHERE id = CAST(? AS INTEGER);\\n\\n-- name: InsertCatalogCollection :exec\\nINSERT INTO collections (id, handle, title, description, status)\\nVALUES (CAST(? AS INTEGER), ?, ?, ?, ?);\\n\\n-- name: UpdateCatalogCollection :exec\\nUPDATE collections SET handle = ?, title = ?, description = ?, revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: SetCatalogCollectionStatus :exec\\nUPDATE collections SET status = ?, revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: TouchCatalogCollection :exec\\nUPDATE collections SET revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: InsertCatalogMember :exec\\nINSERT INTO collection_products (collection_id, product_id, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: DeleteCatalogMember :exec\\nDELETE FROM collection_products WHERE collection_id = CAST(? AS INTEGER) AND product_id = CAST(? AS INTEGER);\\n\\n-- name: SetCatalogMemberPosition :exec\\nUPDATE collection_products SET position = CAST(? AS INTEGER)\\nWHERE collection_id = CAST(? AS INTEGER) AND product_id = CAST(? AS INTEGER);\\n\\n-- name: ExportCatalogProducts :many\\nSELECT CAST(id AS TEXT) AS id, handle, title, vendor, description, status FROM products ORDER BY id;\\n\\n-- name: ExportCatalogDetails :many\\nSELECT CAST(product_id AS TEXT) AS product_id, key, title, body FROM product_details ORDER BY product_id, position;\\n\\n-- name: ExportCatalogOptions :many\\nSELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, name FROM product_options ORDER BY product_id, position;\\n\\n-- name: ExportCatalogOptionValues :many\\nSELECT CAST(id AS TEXT) AS id, CAST(option_id AS TEXT) AS option_id, value FROM product_option_values ORDER BY option_id, position;\\n\\n-- name: ExportCatalogVariants :many\\nSELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, title, CAST(price_minor AS TEXT) AS price_minor, CAST(available AS TEXT) AS available\\nFROM product_variants ORDER BY product_id, position;\\n\\n-- name: ExportCatalogSelections :many\\nSELECT CAST(s.variant_id AS TEXT) AS variant_id, CAST(s.option_id AS TEXT) AS option_id, CAST(s.option_value_id AS TEXT) AS value_id\\nFROM variant_option_values s\\nJOIN product_options o ON o.id = s.option_id\\nORDER BY s.variant_id, o.position;\\n\\n-- name: ExportCatalogImages :many\\nSELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, url, alt_text, CAST(width AS TEXT) AS width, CAST(height AS TEXT) AS height\\nFROM product_images ORDER BY product_id, position;\\n\\n-- name: ExportCatalogCollections :many\\nSELECT CAST(id AS TEXT) AS id, handle, title, description, status FROM collections ORDER BY id;\\n\\n-- name: ExportCatalogMembers :many\\nSELECT CAST(collection_id AS TEXT) AS collection_id, CAST(product_id AS TEXT) AS product_id FROM collection_products ORDER BY collection_id, position;\\n\\n-- name: UpdateImportStoreName :exec\\nUPDATE store SET name = ? WHERE id = 1;\\n\\n-- name: UpdateImportProduct :exec\\nUPDATE products SET handle = ?, title = ?, vendor = ?, description = ?, status = ?, revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: UpdateImportCollection :exec\\nUPDATE collections SET handle = ?, title = ?, description = ?, status = ?, revision = revision + 1 WHERE id = CAST(? AS INTEGER);\\n\\n-- name: DeleteImportDetails :exec\\nDELETE FROM product_details WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: DeleteImportImages :exec\\nDELETE FROM product_images WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: InsertImportImage :exec\\nINSERT INTO product_images (id, product_id, url, alt_text, width, height, position)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: ShiftImportOptionPositions :exec\\nUPDATE product_options SET position = position + 1099511627776 WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: ShiftImportValuePositions :exec\\nUPDATE product_option_values SET position = position + 1099511627776\\nWHERE option_id IN (SELECT id FROM product_options WHERE product_id = CAST(? AS INTEGER));\\n\\n-- name: ShiftImportVariantPositions :exec\\nUPDATE product_variants SET position = position + 1099511627776 WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: UpdateImportOption :exec\\nUPDATE product_options SET name = ?, position = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER);\\n\\n-- name: UpdateImportValue :exec\\nUPDATE product_option_values SET value = ?, position = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER);\\n\\n-- name: UpdateImportVariant :exec\\nUPDATE product_variants SET title = ?, price_minor = CAST(? AS INTEGER), available = CAST(? AS INTEGER), position = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER);\\n\\n-- name: DeleteImportSelectionsOfVariant :exec\\nDELETE FROM variant_option_values WHERE variant_id = CAST(? AS INTEGER);\\n\\n-- name: DeleteImportMembers :exec\\nDELETE FROM collection_products WHERE collection_id = CAST(? AS INTEGER);\\n\",\"checkout.sql\":\"-- Checkout programs (docs/commerce.md). int64 columns are projected with\\n-- CAST(col AS TEXT) and bound through CAST(? AS INTEGER). Session digests are\\n-- 32-byte blobs bound as bytes.\\n\\n-- name: GetCheckoutSession :one\\nSELECT CAST(COALESCE((SELECT r.revision FROM cart_revisions r WHERE r.session_hash = s.token_hash), 0) AS TEXT) AS cart_revision\\nFROM sessions s\\nWHERE s.token_hash = ? AND s.expires_at > CAST(? AS INTEGER);\\n\\n-- name: GetShopSettings :one\\nSELECT CAST(CASE WHEN checkout_paused = 1 OR EXISTS (SELECT 1 FROM work_items WHERE unique_key = 'restore:hold') THEN 1 ELSE 0 END AS TEXT) AS checkout_paused,\\n  CAST(max_active_holds AS TEXT) AS max_active_holds\\nFROM shop_settings WHERE id = 1;\\n\\n-- name: GetCurrentTaxPolicy :one\\nSELECT CAST(version AS TEXT) AS version, mode FROM tax_policies ORDER BY version DESC LIMIT 1;\\n\\n-- name: ListTaxRates :many\\nSELECT region, CAST(rate_ppm AS TEXT) AS rate_ppm, CAST(taxes_lines AS TEXT) AS taxes_lines, CAST(taxes_shipping AS TEXT) AS taxes_shipping\\nFROM tax_rates WHERE version = CAST(? AS INTEGER) ORDER BY region;\\n\\n-- name: GetCurrentShippingPolicy :one\\nSELECT CAST(version AS TEXT) AS version, origin_region,\\n  CAST(free_shipping_threshold_minor AS TEXT) AS free_shipping_threshold_minor,\\n  CAST(local_pickup AS TEXT) AS local_pickup\\nFROM shipping_policies ORDER BY version DESC LIMIT 1;\\n\\n-- name: ListShippingZones :many\\nSELECT name, CAST(flat_rate_minor AS TEXT) AS flat_rate_minor\\nFROM shipping_zones WHERE version = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: ListShippingZoneRegions :many\\nSELECT zone_name, region\\nFROM shipping_zone_regions WHERE version = CAST(? AS INTEGER) ORDER BY zone_name, region;\\n\\n-- name: ListCheckoutCartLines :many\\nSELECT CAST(c.variant_id AS TEXT) AS variant_id, CAST(p.id AS TEXT) AS product_id,\\n  CAST(c.quantity AS TEXT) AS quantity, p.title AS product_title, v.title AS variant_title,\\n  CAST(v.price_minor AS TEXT) AS price_minor, CAST(v.available AS TEXT) AS available,\\n  p.status AS product_status\\nFROM cart_items c\\nJOIN product_variants v ON v.id = c.variant_id\\nJOIN products p ON p.id = v.product_id\\nWHERE c.session_hash = ?\\nORDER BY c.added_at ASC, c.variant_id ASC;\\n\\n-- name: ListCheckoutCartLabels :many\\nSELECT CAST(s.variant_id AS TEXT) AS variant_id, ov.value\\nFROM cart_items c\\nJOIN variant_option_values s ON s.variant_id = c.variant_id\\nJOIN product_options o ON o.id = s.option_id\\nJOIN product_option_values ov ON ov.id = s.option_value_id\\nWHERE c.session_hash = ?\\nORDER BY s.variant_id ASC, o.position ASC;\\n\\n-- name: GetLatestQuoteRevision :one\\nSELECT CAST(COALESCE(MAX(revision), 0) AS TEXT) AS revision FROM quotes WHERE session_hash = ?;\\n\\n-- name: InsertQuote :exec\\nINSERT INTO quotes (\\n  ref, session_hash, revision, cart_revision, currency_code, contact_email, fulfillment,\\n  recipient, line1, line2, city, region, postal_code, country, shipping_zone,\\n  shipping_free_by_threshold, tax_mode, merchandise_minor, shipping_minor, tax_minor, total_minor,\\n  tax_policy_version, shipping_policy_version, created_at, expires_at)\\nVALUES (?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, ?,\\n  ?, ?, ?, ?, ?, ?, ?, ?,\\n  CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER),\\n  CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertQuoteLine :exec\\nINSERT INTO quote_lines (quote_id, position, product_id, variant_id, title, variant_label, unit_price_minor, quantity, line_total_minor)\\nSELECT id, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER)\\nFROM quotes WHERE ref = ?;\\n\\n-- name: InsertQuoteTaxLine :exec\\nINSERT INTO quote_tax_lines (quote_id, position, line_index, taxable_minor, rate_ppm, tax_minor)\\nSELECT id, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER)\\nFROM quotes WHERE ref = ?;\\n\\n-- name: GetQuoteByRef :one\\nSELECT CAST(id AS TEXT) AS id, ref, session_hash, CAST(revision AS TEXT) AS revision,\\n  CAST(cart_revision AS TEXT) AS cart_revision, currency_code, contact_email, fulfillment,\\n  recipient, line1, line2, city, region, postal_code, country, shipping_zone,\\n  CAST(shipping_free_by_threshold AS TEXT) AS shipping_free_by_threshold, tax_mode,\\n  CAST(merchandise_minor AS TEXT) AS merchandise_minor, CAST(shipping_minor AS TEXT) AS shipping_minor,\\n  CAST(tax_minor AS TEXT) AS tax_minor, CAST(total_minor AS TEXT) AS total_minor,\\n  CAST(tax_policy_version AS TEXT) AS tax_policy_version, CAST(shipping_policy_version AS TEXT) AS shipping_policy_version,\\n  CAST(created_at AS TEXT) AS created_at, CAST(expires_at AS TEXT) AS expires_at\\nFROM quotes WHERE ref = ?;\\n\\n-- name: ListQuoteLines :many\\nSELECT CAST(product_id AS TEXT) AS product_id, CAST(variant_id AS TEXT) AS variant_id, title, variant_label,\\n  CAST(unit_price_minor AS TEXT) AS unit_price_minor, CAST(quantity AS TEXT) AS quantity,\\n  CAST(line_total_minor AS TEXT) AS line_total_minor\\nFROM quote_lines WHERE quote_id = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: ListQuoteTaxLines :many\\nSELECT CAST(line_index AS TEXT) AS line_index, CAST(taxable_minor AS TEXT) AS taxable_minor,\\n  CAST(rate_ppm AS TEXT) AS rate_ppm, CAST(tax_minor AS TEXT) AS tax_minor\\nFROM quote_tax_lines WHERE quote_id = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: GetAttemptForQuote :one\\nSELECT CAST(id AS TEXT) AS id, ref, state, provider_session_url FROM checkout_attempts WHERE quote_id = CAST(? AS INTEGER);\\n\\n-- name: GetActiveAttemptForSession :one\\nSELECT CAST(id AS TEXT) AS id, ref, state\\nFROM checkout_attempts WHERE session_hash = ? AND state IN ('accepted', 'handed_off');\\n\\n-- name: CountPinnedAttempts :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n\\nFROM checkout_attempts WHERE state IN ('accepted', 'handed_off', 'superseded', 'blocked');\\n\\n-- name: InsertAttempt :exec\\nINSERT INTO checkout_attempts (ref, quote_id, session_hash, state, accepted_at, hold_release_after, updated_at)\\nVALUES (?, CAST(? AS INTEGER), ?, 'accepted', CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: SupersedeAttempt :execrows\\nUPDATE checkout_attempts SET state = 'superseded', updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state IN ('accepted', 'handed_off');\\n\\n-- name: InsertReservation :exec\\nINSERT INTO reservations (attempt_id, variant_id, quantity, tracked, state, created_at)\\nSELECT id, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), 'held', CAST(? AS INTEGER)\\nFROM checkout_attempts WHERE ref = ?;\\n\\n-- name: InsertWorkItem :exec\\nINSERT INTO work_items (kind, unique_key, payload, state, attempts, next_run_at, created_at, updated_at)\\nVALUES (?, ?, ?, 'pending', 0, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: GetAttemptByRef :one\\nSELECT CAST(a.id AS TEXT) AS id, a.ref, a.state, a.provider_session_url,\\n  q.ref AS quote_ref, CAST(q.id AS TEXT) AS quote_id, CAST(q.total_minor AS TEXT) AS total_minor,\\n  CAST(a.accepted_at AS TEXT) AS accepted_at\\nFROM checkout_attempts a JOIN quotes q ON q.id = a.quote_id\\nWHERE a.ref = ?;\\n\\n-- name: RecordAttemptSession :execrows\\nUPDATE checkout_attempts\\nSET state = CASE WHEN state = 'accepted' THEN 'handed_off' ELSE state END,\\n  provider_session_id = ?, provider_session_url = ?,\\n  provider_session_expires_at = CAST(? AS INTEGER), hold_release_after = CAST(? AS INTEGER), updated_at = CAST(? AS INTEGER)\\nWHERE ref = ? AND state IN ('accepted', 'superseded') AND provider_session_id IS NULL;\\n\\n-- name: SucceedWorkItem :execrows\\nUPDATE work_items\\nSET state = 'succeeded', lease_owner = NULL, lease_expires_at = NULL, failure_class = NULL, last_error = NULL, updated_at = CAST(? AS INTEGER)\\nWHERE unique_key = ? AND state IN ('pending', 'leased');\\n\",\"media.sql\":\"-- Media administration: the upload reservation, adoption by a product image,\\n-- and the cleanup that removes abandoned and unreferenced assets. Every int64\\n-- projects through CAST(col AS TEXT) and binds through CAST(? AS INTEGER).\\n-- References to an asset are read only through the media_references view.\\n\\n-- name: CountMediaAssets :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM media_assets;\\n\\n-- name: CountPendingMedia :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM media_assets WHERE state = 'pending' AND created_at > CAST(? AS INTEGER);\\n\\n-- name: NextMediaId :one\\nSELECT CAST(COALESCE(MAX(id), 0) + 1 AS TEXT) AS id FROM media_assets;\\n\\n-- name: InsertPendingMedia :exec\\nINSERT INTO media_assets (id, sha256, bytes, width, height, content_type, state, created_at)\\nVALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), ?, 'pending', CAST(? AS INTEGER));\\n\\n-- name: GetMediaAsset :one\\nSELECT CAST(id AS TEXT) AS id, sha256, CAST(bytes AS TEXT) AS bytes, CAST(width AS TEXT) AS width, CAST(height AS TEXT) AS height,\\n  content_type, state, CAST(created_at AS TEXT) AS created_at, CAST(ready_at AS TEXT) AS ready_at, CAST(card_id AS TEXT) AS card_id\\nFROM media_assets WHERE id = CAST(? AS INTEGER);\\n\\n-- name: MarkMediaReady :exec\\nUPDATE media_assets SET state = 'ready', ready_at = CAST(? AS INTEGER), card_id = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = 'pending';\\n\\n-- name: ListExpiredPendingMedia :many\\nSELECT CAST(id AS TEXT) AS id, sha256, content_type\\nFROM media_assets\\nWHERE state = 'pending' AND created_at <= CAST(? AS INTEGER)\\nORDER BY id\\nLIMIT 100;\\n\\n-- name: ListUnreferencedMedia :many\\nSELECT CAST(a.id AS TEXT) AS id, a.sha256, a.content_type\\nFROM media_assets a\\nWHERE a.state = 'ready' AND a.ready_at <= CAST(? AS INTEGER)\\n  AND NOT EXISTS (SELECT 1 FROM media_references r WHERE r.media_id = a.id)\\nORDER BY (a.card_id IS NULL), a.id\\nLIMIT 100;\\n\\n-- name: DeleteMediaAsset :exec\\nDELETE FROM media_assets WHERE id = CAST(? AS INTEGER);\\n\\n-- name: CatalogNextImagePosition :one\\nSELECT CAST(COALESCE(MAX(position) + 1, 0) AS TEXT) AS position FROM product_images WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: CountCatalogProductImages :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM product_images WHERE product_id = CAST(? AS INTEGER);\\n\\n-- name: GetCatalogProductImage :one\\nSELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, CAST(position AS TEXT) AS position,\\n  CAST(media_id AS TEXT) AS media_id\\nFROM product_images WHERE id = CAST(? AS INTEGER);\\n\\n-- name: InsertCatalogMediaImage :exec\\nINSERT INTO product_images (id, product_id, url, alt_text, width, height, media_id, position)\\nVALUES ((SELECT COALESCE(MAX(id), 0) + 1 FROM product_images), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: DeleteCatalogProductImage :exec\\nDELETE FROM product_images WHERE id = CAST(? AS INTEGER);\\n\\n-- name: SetCatalogImageAlt :exec\\nUPDATE product_images SET alt_text = ? WHERE id = CAST(? AS INTEGER);\\n\\n-- name: GetCatalogImageAbove :one\\nSELECT CAST(id AS TEXT) AS id, CAST(position AS TEXT) AS position FROM product_images\\nWHERE product_id = CAST(? AS INTEGER) AND position < CAST(? AS INTEGER) ORDER BY position DESC LIMIT 1;\\n\\n-- name: GetCatalogImageBelow :one\\nSELECT CAST(id AS TEXT) AS id, CAST(position AS TEXT) AS position FROM product_images\\nWHERE product_id = CAST(? AS INTEGER) AND position > CAST(? AS INTEGER) ORDER BY position ASC LIMIT 1;\\n\\n-- name: SetCatalogImagePosition :exec\\nUPDATE product_images SET position = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER);\\n\",\"settings.sql\":\"-- Shop settings and policy administration. A policy change is a new immutable\\n-- version (migration 0006); the current policy is the highest version. Every\\n-- int64 projects through CAST(col AS TEXT) and binds through CAST(? AS INTEGER).\\n\\n-- name: GetSettingsRow :one\\nSELECT CAST(checkout_paused AS TEXT) AS checkout_paused, CAST(max_active_holds AS TEXT) AS max_active_holds, CAST(revision AS TEXT) AS revision\\nFROM shop_settings WHERE id = 1;\\n\\n-- name: UpdateShopSettings :execrows\\nUPDATE shop_settings\\nSET checkout_paused = CAST(? AS INTEGER), max_active_holds = CAST(? AS INTEGER), revision = revision + 1\\nWHERE id = 1 AND revision = CAST(? AS INTEGER);\\n\\n-- name: GetSettingsTaxPolicy :one\\nSELECT CAST(version AS TEXT) AS version, mode, CAST(created_at AS TEXT) AS created_at\\nFROM tax_policies ORDER BY version DESC LIMIT 1;\\n\\n-- name: GetSettingsShippingPolicy :one\\nSELECT CAST(version AS TEXT) AS version, origin_region,\\n  CAST(free_shipping_threshold_minor AS TEXT) AS free_shipping_threshold_minor,\\n  CAST(local_pickup AS TEXT) AS local_pickup, CAST(created_at AS TEXT) AS created_at\\nFROM shipping_policies ORDER BY version DESC LIMIT 1;\\n\\n-- name: InsertTaxPolicy :exec\\nINSERT INTO tax_policies (version, mode, created_at) VALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER));\\n\\n-- name: InsertTaxRate :exec\\nINSERT INTO tax_rates (version, region, rate_ppm, taxes_lines, taxes_shipping)\\nVALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertShippingPolicy :exec\\nINSERT INTO shipping_policies (version, origin_region, free_shipping_threshold_minor, local_pickup, created_at)\\nVALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertShippingZone :exec\\nINSERT INTO shipping_zones (version, name, flat_rate_minor, position)\\nVALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertShippingZoneRegion :exec\\nINSERT INTO shipping_zone_regions (version, region, zone_name) VALUES (CAST(? AS INTEGER), ?, ?);\\n\",\"shop.sql\":\"-- Shop identity, information pages, and their review marks (migration 0011).\\n-- Every int64 projects through CAST(col AS TEXT) and binds through CAST(? AS INTEGER).\\n\\n-- name: GetShopIdentity :one\\nSELECT s.name, p.description, p.contact_email, p.contact_phone,\\n  CAST(p.revision AS TEXT) AS revision, CAST(p.updated_at AS TEXT) AS updated_at\\nFROM store s, shop_profile p\\nWHERE s.id = 1 AND p.id = 1;\\n\\n-- name: UpdateShopName :exec\\nUPDATE store SET name = ? WHERE id = 1;\\n\\n-- name: UpdateShopProfile :execrows\\nUPDATE shop_profile\\nSET description = ?, contact_email = ?, contact_phone = ?, revision = revision + 1, updated_at = CAST(? AS INTEGER)\\nWHERE id = 1 AND revision = CAST(? AS INTEGER);\\n\\n-- name: ListShopPageStates :many\\nSELECT p.kind, p.blocks, CAST(p.revision AS TEXT) AS revision, CAST(p.updated_at AS TEXT) AS updated_at,\\n  r.reviewed_by, CAST(r.reviewed_revision AS TEXT) AS reviewed_revision, CAST(r.reviewed_at AS TEXT) AS reviewed_at\\nFROM shop_pages p\\nLEFT JOIN shop_page_reviews r ON r.kind = p.kind\\nORDER BY p.kind ASC;\\n\\n-- name: GetShopPageState :one\\nSELECT p.kind, p.blocks, CAST(p.revision AS TEXT) AS revision, CAST(p.updated_at AS TEXT) AS updated_at,\\n  r.reviewed_by, CAST(r.reviewed_revision AS TEXT) AS reviewed_revision, CAST(r.reviewed_at AS TEXT) AS reviewed_at\\nFROM shop_pages p\\nLEFT JOIN shop_page_reviews r ON r.kind = p.kind\\nWHERE p.kind = ?;\\n\\n-- name: UpdateShopPage :execrows\\nUPDATE shop_pages\\nSET blocks = ?, revision = revision + 1, updated_at = CAST(? AS INTEGER)\\nWHERE kind = ? AND revision = CAST(? AS INTEGER);\\n\\n-- name: UpsertShopPageReview :exec\\nINSERT INTO shop_page_reviews (kind, reviewed_revision, reviewed_by, reviewed_at)\\nVALUES (?, CAST(? AS INTEGER), ?, CAST(? AS INTEGER))\\nON CONFLICT (kind) DO UPDATE SET reviewed_revision = excluded.reviewed_revision, reviewed_by = excluded.reviewed_by, reviewed_at = excluded.reviewed_at;\\n\",\"work.sql\":\"-- name: ListClaimableWork :many\\nSELECT CAST(id AS TEXT) AS id, kind, unique_key, payload, CAST(attempts AS TEXT) AS attempts\\nFROM work_items\\nWHERE ((state = 'pending' AND next_run_at <= CAST(? AS INTEGER)) OR (state = 'leased' AND lease_expires_at <= CAST(? AS INTEGER)))\\n  AND NOT EXISTS (SELECT 1 FROM work_items WHERE unique_key = 'restore:hold')\\nORDER BY CASE WHEN state = 'pending' THEN next_run_at ELSE lease_expires_at END, id\\nLIMIT CAST(? AS INTEGER);\\n\\n-- name: ClaimWorkItem :execrows\\nUPDATE work_items\\nSET state = 'leased', attempts = CAST(? AS INTEGER), lease_owner = ?, lease_expires_at = CAST(? AS INTEGER), updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND attempts = CAST(? AS INTEGER)\\n  AND ((state = 'pending' AND next_run_at <= CAST(? AS INTEGER)) OR (state = 'leased' AND lease_expires_at <= CAST(? AS INTEGER)))\\n  AND NOT EXISTS (SELECT 1 FROM work_items WHERE unique_key = 'restore:hold');\\n\\n-- name: CompleteWorkItem :execrows\\nUPDATE work_items\\nSET state = 'succeeded', lease_owner = NULL, lease_expires_at = NULL, failure_class = NULL, last_error = NULL, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = 'leased' AND lease_owner = ? AND attempts = CAST(? AS INTEGER);\\n\\n-- name: RescheduleWorkItem :execrows\\nUPDATE work_items\\nSET state = 'pending', attempts = 0, next_run_at = CAST(? AS INTEGER), payload = ?, lease_owner = NULL, lease_expires_at = NULL, failure_class = NULL, last_error = NULL, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = 'leased' AND lease_owner = ? AND attempts = CAST(? AS INTEGER);\\n\\n-- name: FailWorkItem :execrows\\nUPDATE work_items\\nSET state = ?, next_run_at = CAST(? AS INTEGER), lease_owner = NULL, lease_expires_at = NULL, failure_class = ?, last_error = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = 'leased' AND lease_owner = ? AND attempts = CAST(? AS INTEGER);\\n\\n-- name: KillWorkItem :execrows\\nUPDATE work_items\\nSET state = 'dead', lease_owner = NULL, lease_expires_at = NULL, failure_class = ?, last_error = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND attempts = CAST(? AS INTEGER) AND state IN ('pending', 'leased');\\n\\n-- name: RequeueWorkItem :execrows\\nUPDATE work_items\\nSET state = 'pending', attempts = 0, next_run_at = CAST(? AS INTEGER), failure_class = NULL, last_error = NULL, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = 'dead';\\n\\n-- name: GetNextWorkAt :one\\nSELECT CAST(MIN(due_at) AS TEXT) AS next_at FROM (\\n  SELECT next_run_at AS due_at FROM work_items WHERE state = 'pending' AND NOT EXISTS (SELECT 1 FROM work_items WHERE unique_key = 'restore:hold')\\n  UNION ALL\\n  SELECT lease_expires_at AS due_at FROM work_items WHERE state = 'leased' AND NOT EXISTS (SELECT 1 FROM work_items WHERE unique_key = 'restore:hold')\\n);\\n\\n-- name: EnsureWorkItem :execrows\\nINSERT INTO work_items (kind, unique_key, payload, state, attempts, next_run_at, created_at, updated_at)\\nVALUES (?, ?, ?, 'pending', 0, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT (unique_key) DO NOTHING;\\n\\n-- name: ListDeadWork :many\\nSELECT CAST(id AS TEXT) AS id, kind, unique_key, CAST(attempts AS TEXT) AS attempts, failure_class, last_error, CAST(updated_at AS TEXT) AS updated_at\\nFROM work_items WHERE state = 'dead' ORDER BY id LIMIT 100;\\n\\n-- name: CountWorkByState :many\\nSELECT state, CAST(COUNT(*) AS TEXT) AS n FROM work_items GROUP BY state ORDER BY state;\\n\\n-- name: DeleteSucceededWork :execrows\\nDELETE FROM work_items WHERE state = 'succeeded' AND updated_at <= CAST(? AS INTEGER);\\n\\n-- name: InsertProviderEvent :execrows\\nINSERT INTO provider_events (stripe_event_id, event_type, object_id, event_created_at, received_at, processed_at, raw_body)\\nVALUES (?, ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), ?)\\nON CONFLICT (stripe_event_id) DO NOTHING;\\n\\n-- name: GetProviderEvent :one\\nSELECT stripe_event_id, event_type, object_id, CAST(event_created_at AS TEXT) AS event_created_at, CAST(received_at AS TEXT) AS received_at, CAST(processed_at AS TEXT) AS processed_at\\nFROM provider_events WHERE stripe_event_id = ?;\\n\\n-- name: MarkProviderEventProcessed :execrows\\nUPDATE provider_events SET processed_at = CAST(? AS INTEGER) WHERE stripe_event_id = ? AND processed_at IS NULL;\\n\\n-- name: PurgeProviderEventBodies :execrows\\nUPDATE provider_events SET raw_body = NULL, raw_purged_at = CAST(? AS INTEGER)\\nWHERE raw_body IS NOT NULL AND received_at <= CAST(? AS INTEGER);\\n\\n-- name: GetRestoreHold :one\\nSELECT payload FROM work_items WHERE unique_key = 'restore:hold';\\n\\n-- name: ListRestorePayments :many\\nSELECT p.payment_intent_id, p.state\\nFROM payments p\\nWHERE p.state IN ('capture_pending', 'capture_unknown', 'void_unknown')\\n  OR EXISTS (\\n    SELECT 1 FROM provider_operations o\\n    WHERE o.kind IN ('capture', 'cancel_pi') AND o.subject_id = p.payment_intent_id AND o.state IN ('in_flight', 'unknown')\\n  )\\nORDER BY p.id\\nLIMIT 1000;\\n\\n-- name: ListRestoreRefunds :many\\nSELECT CAST(r.id AS TEXT) AS id, p.payment_intent_id, r.state\\nFROM refunds r JOIN payments p ON p.order_id = r.order_id\\nWHERE r.state IN ('pending', 'requires_action')\\nORDER BY r.id\\nLIMIT 1000;\\n\\n-- name: MarkRestoreReconciled :execrows\\nUPDATE work_items SET payload = ?, updated_at = CAST(? AS INTEGER) WHERE unique_key = 'restore:hold';\\n\\n-- name: ReleaseRestoreHold :execrows\\nDELETE FROM work_items WHERE unique_key = 'restore:hold';\\n\\n-- name: GetOperationsStatus :one\\nSELECT\\n  CAST((SELECT COUNT(*) FROM payments WHERE state IN ('authorized', 'in_review', 'capture_pending')) AS TEXT) AS pending_payments,\\n  CAST((SELECT MIN(created_at) FROM payments WHERE state IN ('authorized', 'in_review', 'capture_pending')) AS TEXT) AS pending_payments_since,\\n  CAST((SELECT COUNT(*) FROM provider_operations WHERE state = 'unknown') AS TEXT) AS unknown_operations,\\n  CAST((SELECT MIN(updated_at) FROM provider_operations WHERE state = 'unknown') AS TEXT) AS unknown_operations_since,\\n  CAST((SELECT COUNT(*) FROM provider_events WHERE processed_at IS NULL) AS TEXT) AS unprocessed_events,\\n  CAST((SELECT MIN(received_at) FROM provider_events WHERE processed_at IS NULL) AS TEXT) AS unprocessed_events_since,\\n  CAST((SELECT COUNT(*) FROM work_items WHERE kind != 'restore_hold' AND ((state = 'pending' AND next_run_at <= CAST(? AS INTEGER)) OR (state = 'leased' AND lease_expires_at <= CAST(? AS INTEGER)))) AS TEXT) AS due_work,\\n  CAST((SELECT MIN(CASE WHEN state = 'pending' THEN next_run_at ELSE lease_expires_at END) FROM work_items WHERE kind != 'restore_hold' AND ((state = 'pending' AND next_run_at <= CAST(? AS INTEGER)) OR (state = 'leased' AND lease_expires_at <= CAST(? AS INTEGER)))) AS TEXT) AS due_work_since,\\n  CAST((SELECT COUNT(*) FROM work_items WHERE state = 'dead') AS TEXT) AS dead_work,\\n  CAST((SELECT MIN(updated_at) FROM work_items WHERE state = 'dead') AS TEXT) AS dead_work_since,\\n  CAST((SELECT COUNT(*) FROM refunds WHERE state IN ('pending', 'requires_action')) AS TEXT) AS open_refunds,\\n  CAST((SELECT MIN(created_at) FROM refunds WHERE state IN ('pending', 'requires_action')) AS TEXT) AS open_refunds_since,\\n  CAST((SELECT COUNT(*) FROM refunds WHERE state IN ('pending', 'requires_action') AND created_at <= CAST(? AS INTEGER)) AS TEXT) AS stalled_refunds,\\n  CAST((SELECT COUNT(*) FROM work_items WHERE unique_key = 'restore:hold') AS TEXT) AS held;\\n\",\"payments.sql\":\"-- Payment, order, and provider-operation programs (docs/commerce.md). int64\\n-- columns are projected with CAST(col AS TEXT) and bound through\\n-- CAST(? AS INTEGER).\\n\\n-- name: GetPaymentAttempt :one\\nSELECT CAST(a.id AS TEXT) AS id, a.ref, a.state, a.session_hash, a.provider_session_id, a.provider_session_url,\\n  CAST(a.provider_session_expires_at AS TEXT) AS provider_session_expires_at, CAST(a.hold_release_after AS TEXT) AS hold_release_after,\\n  CAST(a.accepted_at AS TEXT) AS accepted_at, CAST(q.id AS TEXT) AS quote_id, q.ref AS quote_ref,\\n  CAST(q.total_minor AS TEXT) AS total_minor, q.currency_code\\nFROM checkout_attempts a JOIN quotes q ON q.id = a.quote_id\\nWHERE a.ref = ?;\\n\\n-- name: ListAttemptReservations :many\\nSELECT CAST(variant_id AS TEXT) AS variant_id, CAST(quantity AS TEXT) AS quantity, CAST(tracked AS TEXT) AS tracked, state\\nFROM reservations WHERE attempt_id = CAST(? AS INTEGER) ORDER BY variant_id;\\n\\n-- name: SetAttemptState :execrows\\nUPDATE checkout_attempts SET state = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = ?;\\n\\n-- name: SetReservationsState :execrows\\nUPDATE reservations SET state = ?, resolved_at = COALESCE(resolved_at, CAST(? AS INTEGER))\\nWHERE attempt_id = CAST(? AS INTEGER) AND state = ?;\\n\\n-- name: GetOperation :one\\nSELECT CAST(id AS TEXT) AS id, state, idempotency_key, CAST(attempts AS TEXT) AS attempts, provider_object_id,\\n  CAST(created_at AS TEXT) AS created_at, CAST(updated_at AS TEXT) AS updated_at\\nFROM provider_operations WHERE kind = ? AND subject_id = ?;\\n\\n-- name: InsertOperation :execrows\\nINSERT INTO provider_operations (kind, subject_id, idempotency_key, state, attempts, created_at, updated_at)\\nVALUES (?, ?, ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT (kind, subject_id) DO NOTHING;\\n\\n-- name: SetOperationState :execrows\\nUPDATE provider_operations\\nSET state = ?, attempts = CAST(? AS INTEGER), provider_object_id = COALESCE(?, provider_object_id), last_error = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = ?;\\n\\n-- name: GetOrderForAttempt :one\\nSELECT CAST(o.id AS TEXT) AS id, CAST(o.number AS TEXT) AS number, p.payment_intent_id\\nFROM orders o JOIN payments p ON p.order_id = o.id\\nWHERE o.attempt_id = CAST(? AS INTEGER);\\n\\n-- name: InsertOrder :execrows\\nINSERT INTO orders (\\n  number, attempt_id, quote_id, currency_code, contact_email, fulfillment,\\n  recipient, line1, line2, city, region, postal_code, country, shipping_zone, shipping_free_by_threshold, tax_mode,\\n  merchandise_minor, shipping_minor, shipping_tax_minor, shipping_tax_rate_ppm, tax_minor, total_minor,\\n  tax_policy_version, shipping_policy_version, allocation, placed_at)\\nSELECT (SELECT COALESCE(MAX(number), 0) + 1 FROM orders), CAST(? AS INTEGER), q.id, q.currency_code, q.contact_email, q.fulfillment,\\n  q.recipient, q.line1, q.line2, q.city, q.region, q.postal_code, q.country, q.shipping_zone, q.shipping_free_by_threshold, q.tax_mode,\\n  q.merchandise_minor, q.shipping_minor,\\n  COALESCE((SELECT t.tax_minor FROM quote_tax_lines t WHERE t.quote_id = q.id AND t.line_index IS NULL), 0),\\n  COALESCE((SELECT t.rate_ppm FROM quote_tax_lines t WHERE t.quote_id = q.id AND t.line_index IS NULL), 0),\\n  q.tax_minor, q.total_minor, q.tax_policy_version, q.shipping_policy_version, ?, CAST(? AS INTEGER)\\nFROM quotes q WHERE q.id = CAST(? AS INTEGER);\\n\\n-- name: InsertOrderLines :execrows\\nINSERT INTO order_lines (\\n  order_id, position, product_id, variant_id, title, variant_label, unit_price_minor, quantity, line_total_minor,\\n  taxable_minor, tax_rate_ppm, tax_minor, image_media_id)\\nSELECT o.id, l.position, l.product_id, l.variant_id, l.title, l.variant_label, l.unit_price_minor, l.quantity, l.line_total_minor,\\n  COALESCE(t.taxable_minor, 0), COALESCE(t.rate_ppm, 0), COALESCE(t.tax_minor, 0),\\n  (SELECT i.media_id FROM product_images i WHERE i.product_id = l.product_id AND i.media_id IS NOT NULL ORDER BY i.position, i.id LIMIT 1)\\nFROM orders o\\nJOIN quote_lines l ON l.quote_id = o.quote_id\\nLEFT JOIN quote_tax_lines t ON t.quote_id = l.quote_id AND t.line_index = l.position\\nWHERE o.attempt_id = CAST(? AS INTEGER);\\n\\n-- name: InsertPayment :exec\\nINSERT INTO payments (order_id, payment_intent_id, state, currency_code, amount_authorized_minor, review_id, created_at, updated_at)\\nSELECT id, ?, ?, currency_code, total_minor, ?, CAST(? AS INTEGER), CAST(? AS INTEGER)\\nFROM orders WHERE attempt_id = CAST(? AS INTEGER);\\n\\n-- name: GetPaymentByIntent :one\\nSELECT CAST(p.id AS TEXT) AS id, CAST(p.order_id AS TEXT) AS order_id, CAST(o.number AS TEXT) AS number,\\n  CAST(o.attempt_id AS TEXT) AS attempt_id, a.ref AS attempt_ref, p.state,\\n  CAST(p.amount_authorized_minor AS TEXT) AS amount_authorized_minor, CAST(p.amount_captured_minor AS TEXT) AS amount_captured_minor,\\n  p.currency_code, p.review_id\\nFROM payments p JOIN orders o ON o.id = p.order_id JOIN checkout_attempts a ON a.id = o.attempt_id\\nWHERE p.payment_intent_id = ?;\\n\\n-- name: SetPaymentState :execrows\\nUPDATE payments SET state = ?, amount_captured_minor = CAST(? AS INTEGER), review_id = COALESCE(?, review_id), updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = ?;\\n\\n-- name: UpsertOrderException :exec\\nINSERT INTO order_exceptions (attempt_id, order_id, kind, provider_object_id, state, detail, opened_at, closed_at, updated_at)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT (kind, provider_object_id) DO UPDATE SET\\n  order_id = COALESCE(order_exceptions.order_id, excluded.order_id),\\n  state = excluded.state,\\n  detail = excluded.detail,\\n  closed_at = CASE WHEN excluded.state = 'closed' THEN COALESCE(order_exceptions.closed_at, excluded.closed_at) ELSE NULL END,\\n  updated_at = excluded.updated_at;\\n\\n-- name: ScheduleWork :execrows\\nINSERT INTO work_items (kind, unique_key, payload, state, attempts, next_run_at, created_at, updated_at)\\nVALUES (?, ?, ?, 'pending', 0, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT (unique_key) DO UPDATE SET\\n  state = 'pending', attempts = 0, next_run_at = excluded.next_run_at, payload = excluded.payload,\\n  failure_class = NULL, last_error = NULL, updated_at = excluded.updated_at\\nWHERE work_items.state = 'succeeded';\\n\\n-- name: SetPendingWorkDue :execrows\\nUPDATE work_items SET next_run_at = CAST(? AS INTEGER), updated_at = CAST(? AS INTEGER)\\nWHERE unique_key = ? AND state = 'pending';\\n\\n-- name: GetOrderStatus :one\\nSELECT CAST(o.id AS TEXT) AS id, CAST(o.number AS TEXT) AS number, a.ref AS attempt_ref, p.state AS payment_state,\\n  o.currency_code, CAST(o.total_minor AS TEXT) AS total_minor, CAST(o.placed_at AS TEXT) AS placed_at,\\n  CAST((SELECT COUNT(*) FROM order_exceptions e WHERE e.order_id = o.id AND e.state = 'open') AS TEXT) AS open_exceptions,\\n  o.fulfillment, o.city, o.region\\nFROM orders o JOIN checkout_attempts a ON a.id = o.attempt_id JOIN payments p ON p.order_id = o.id\\nWHERE o.number = CAST(? AS INTEGER)\\n  AND EXISTS (SELECT 1 FROM order_access g WHERE g.order_id = o.id AND g.digest = ? AND g.revoked_at IS NULL AND g.expires_at > CAST(? AS INTEGER));\\n\\n-- name: ListOrderLines :many\\nSELECT CAST(product_id AS TEXT) AS product_id, CAST(variant_id AS TEXT) AS variant_id, title, variant_label,\\n  CAST(unit_price_minor AS TEXT) AS unit_price_minor, CAST(quantity AS TEXT) AS quantity, CAST(line_total_minor AS TEXT) AS line_total_minor,\\n  CAST(taxable_minor AS TEXT) AS taxable_minor, CAST(tax_rate_ppm AS TEXT) AS tax_rate_ppm, CAST(tax_minor AS TEXT) AS tax_minor,\\n  CAST(image_media_id AS TEXT) AS image_media_id\\nFROM order_lines WHERE order_id = CAST(? AS INTEGER) ORDER BY position;\\n\\n-- name: ListOrderExceptions :many\\nSELECT CAST(id AS TEXT) AS id, kind, provider_object_id, state, detail, CAST(opened_at AS TEXT) AS opened_at, CAST(closed_at AS TEXT) AS closed_at\\nFROM order_exceptions WHERE order_id = CAST(? AS INTEGER) ORDER BY id;\\n\\n-- name: ListAttemptExceptions :many\\nSELECT CAST(e.id AS TEXT) AS id, e.kind, e.provider_object_id, e.state, e.detail, CAST(e.opened_at AS TEXT) AS opened_at, CAST(e.closed_at AS TEXT) AS closed_at\\nFROM order_exceptions e JOIN checkout_attempts a ON a.id = e.attempt_id\\nWHERE a.ref = ? ORDER BY e.id;\\n\\n-- name: ListStalledAttempts :many\\nSELECT a.ref\\nFROM checkout_attempts a\\nWHERE a.state IN ('accepted', 'handed_off', 'superseded') AND a.hold_release_after <= CAST(? AS INTEGER)\\n  AND NOT EXISTS (SELECT 1 FROM work_items w WHERE w.unique_key = 'hold_expiry:' || a.ref AND w.state IN ('pending', 'leased', 'dead'))\\nORDER BY a.hold_release_after, a.id\\nLIMIT CAST(? AS INTEGER);\\n\\n-- name: ListStalledPayments :many\\nSELECT p.payment_intent_id, p.state\\nFROM payments p\\nWHERE p.state IN ('authorized', 'capture_pending', 'capture_unknown') AND p.updated_at <= CAST(? AS INTEGER)\\n  AND NOT EXISTS (SELECT 1 FROM work_items w WHERE w.unique_key = 'capture:' || p.payment_intent_id AND w.state IN ('pending', 'leased', 'dead'))\\nORDER BY p.updated_at, p.id\\nLIMIT CAST(? AS INTEGER);\\n\",\"orders.sql\":\"-- Order administration programs (docs/admin.md). int64 columns are projected\\n-- with CAST(col AS TEXT) and bound through CAST(? AS INTEGER).\\n\\n-- name: ListOrders :many\\nSELECT CAST(o.number AS TEXT) AS number, CAST(o.placed_at AS TEXT) AS placed_at, o.contact_email, o.currency_code,\\n  CAST((SELECT currency_exponent FROM store WHERE id = 1) AS TEXT) AS currency_exponent,\\n  CAST(o.total_minor AS TEXT) AS total_minor, o.fulfillment, o.fulfillment_status, p.state AS payment_state,\\n  CAST((SELECT COUNT(*) FROM order_exceptions e WHERE e.order_id = o.id AND e.state = 'open') AS TEXT) AS open_exceptions,\\n  CAST((SELECT COALESCE(SUM(l.quantity), 0) FROM order_lines l WHERE l.order_id = o.id) AS TEXT) AS item_count\\nFROM orders o JOIN payments p ON p.order_id = o.id\\nWHERE (CAST(? AS INTEGER) IS NULL OR o.number < CAST(? AS INTEGER))\\n  AND (CAST(? AS INTEGER) IS NULL OR o.number = CAST(? AS INTEGER))\\n  AND (CAST(? AS INTEGER) IS NULL OR o.placed_at >= CAST(? AS INTEGER))\\n  AND (CAST(? AS INTEGER) IS NULL OR o.placed_at < CAST(? AS INTEGER))\\n  AND (? IS NULL OR p.state = ?)\\n  AND (? IS NULL OR o.fulfillment_status = ?)\\n  AND (? IS NULL OR o.email_digest = ?)\\nORDER BY o.number DESC\\nLIMIT CAST(? AS INTEGER);\\n\\n-- name: GetOrderDetail :one\\nSELECT CAST(o.id AS TEXT) AS id, CAST(o.number AS TEXT) AS number, CAST(o.revision AS TEXT) AS revision, CAST(o.attempt_id AS TEXT) AS attempt_id,\\n  o.contact_email, o.currency_code, CAST((SELECT currency_exponent FROM store WHERE id = 1) AS TEXT) AS currency_exponent, o.fulfillment, o.fulfillment_status, o.recipient, o.line1, o.line2, o.city, o.region, o.postal_code, o.country,\\n  o.shipping_zone, CAST(o.merchandise_minor AS TEXT) AS merchandise_minor, CAST(o.shipping_minor AS TEXT) AS shipping_minor,\\n  CAST(o.shipping_tax_minor AS TEXT) AS shipping_tax_minor, CAST(o.tax_minor AS TEXT) AS tax_minor, CAST(o.total_minor AS TEXT) AS total_minor,\\n  o.allocation, CAST(o.placed_at AS TEXT) AS placed_at, p.payment_intent_id, p.state AS payment_state,\\n  CAST(p.amount_authorized_minor AS TEXT) AS amount_authorized_minor, CAST(p.amount_captured_minor AS TEXT) AS amount_captured_minor\\nFROM orders o JOIN payments p ON p.order_id = o.id\\nWHERE o.number = CAST(? AS INTEGER);\\n\\n-- name: ListOrderLineStates :many\\nSELECT CAST(l.position AS TEXT) AS position, CAST(l.variant_id AS TEXT) AS variant_id, l.title, l.variant_label,\\n  CAST(l.unit_price_minor AS TEXT) AS unit_price_minor, CAST(l.quantity AS TEXT) AS quantity, CAST(l.line_total_minor AS TEXT) AS line_total_minor,\\n  CAST(l.tax_minor AS TEXT) AS tax_minor, CAST(f.shipped AS TEXT) AS shipped, CAST(f.canceled AS TEXT) AS canceled, CAST(f.returned AS TEXT) AS returned,\\n  CAST(COALESCE((SELECT SUM(r.quantity) FROM restocks r WHERE r.order_id = l.order_id AND r.position = l.position), 0) AS TEXT) AS restocked\\nFROM order_lines l JOIN line_fulfillment f ON f.order_id = l.order_id AND f.position = l.position\\nWHERE l.order_id = CAST(? AS INTEGER)\\nORDER BY l.position;\\n\\n-- name: ListOrderShipments :many\\nSELECT CAST(id AS TEXT) AS id, CAST(sequence AS TEXT) AS sequence, carrier, tracking_number, tracking_url, actor, CAST(shipped_at AS TEXT) AS shipped_at\\nFROM fulfillments WHERE order_id = CAST(? AS INTEGER) ORDER BY sequence;\\n\\n-- name: ListOrderShipmentLines :many\\nSELECT CAST(fulfillment_id AS TEXT) AS fulfillment_id, CAST(position AS TEXT) AS position, CAST(quantity AS TEXT) AS quantity\\nFROM fulfillment_lines WHERE order_id = CAST(? AS INTEGER) ORDER BY fulfillment_id, position;\\n\\n-- name: ListOrderNotes :many\\nSELECT CAST(id AS TEXT) AS id, body, actor, CAST(created_at AS TEXT) AS created_at\\nFROM order_notes WHERE order_id = CAST(? AS INTEGER) ORDER BY id DESC LIMIT 50;\\n\\n-- name: ListOrderTimeline :many\\nSELECT CAST(id AS TEXT) AS id, actor, action, summary, CAST(created_at AS TEXT) AS created_at FROM (\\n  SELECT id, actor, action, summary, created_at FROM audit_events WHERE entity_kind = 'order' AND entity_id = ? ORDER BY id DESC LIMIT 200\\n) ORDER BY id;\\n\\n-- name: ListOrderRefunds :many\\nSELECT CAST(id AS TEXT) AS id, state, CAST(amount_minor AS TEXT) AS amount_minor, reason, failure_reason, CAST(created_at AS TEXT) AS created_at\\nFROM refunds WHERE order_id = CAST(? AS INTEGER) ORDER BY id;\\n\\n-- name: GetShipmentSequence :one\\nSELECT CAST(COALESCE(MAX(sequence), 0) AS TEXT) AS sequence FROM fulfillments WHERE order_id = CAST(? AS INTEGER);\\n\\n-- name: InsertShipment :execrows\\nINSERT INTO fulfillments (order_id, sequence, carrier, tracking_number, tracking_url, actor, shipped_at)\\nSELECT CAST(? AS INTEGER), COALESCE(MAX(sequence), 0) + 1, ?, ?, ?, ?, CAST(? AS INTEGER)\\nFROM fulfillments WHERE order_id = CAST(? AS INTEGER);\\n\\n-- name: InsertShipmentLine :execrows\\nINSERT INTO fulfillment_lines (fulfillment_id, order_id, position, quantity)\\nSELECT id, order_id, CAST(? AS INTEGER), CAST(? AS INTEGER) FROM fulfillments WHERE order_id = CAST(? AS INTEGER) AND sequence = CAST(? AS INTEGER);\\n\\n-- name: AddLineShipped :execrows\\nUPDATE line_fulfillment SET shipped = shipped + CAST(? AS INTEGER)\\nWHERE order_id = CAST(? AS INTEGER) AND position = CAST(? AS INTEGER);\\n\\n-- name: BumpOrderRevision :execrows\\nUPDATE orders SET revision = revision + 1 WHERE id = CAST(? AS INTEGER) AND revision = CAST(? AS INTEGER);\\n\\n-- name: InsertOrderNote :execrows\\nINSERT INTO order_notes (order_id, body, actor, created_at) VALUES (CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER));\\n\\n-- name: GetOrderSearchKey :one\\nSELECT key FROM order_search_key WHERE id = 1;\\n\\n-- name: GetOrderContactEmail :one\\nSELECT contact_email FROM orders WHERE id = CAST(? AS INTEGER);\\n\\n-- name: SetOrderEmailDigest :execrows\\nUPDATE orders SET email_digest = ? WHERE id = CAST(? AS INTEGER);\\n\",\"refunds.sql\":\"-- Refund, cancellation, return, and restock programs (docs/commerce.md). int64\\n-- columns are projected with CAST(col AS TEXT) and bound through CAST(? AS INTEGER).\\n\\n-- name: GetRefund :one\\nSELECT CAST(r.id AS TEXT) AS id, CAST(r.order_id AS TEXT) AS order_id, CAST(o.number AS TEXT) AS number, r.state,\\n  CAST(r.amount_minor AS TEXT) AS amount_minor, r.provider_refund_id, p.payment_intent_id, o.currency_code, CAST(r.created_at AS TEXT) AS created_at\\nFROM refunds r JOIN orders o ON o.id = r.order_id JOIN payments p ON p.order_id = o.id\\nWHERE r.id = CAST(? AS INTEGER);\\n\\n-- name: GetRefundByProviderId :one\\nSELECT CAST(r.id AS TEXT) AS id, CAST(r.order_id AS TEXT) AS order_id, CAST(o.number AS TEXT) AS number, r.state,\\n  CAST(r.amount_minor AS TEXT) AS amount_minor, r.provider_refund_id, p.payment_intent_id, o.currency_code, CAST(r.created_at AS TEXT) AS created_at\\nFROM refunds r JOIN orders o ON o.id = r.order_id JOIN payments p ON p.order_id = o.id\\nWHERE r.provider_refund_id = ?;\\n\\n-- name: GetNewestRefund :one\\nSELECT CAST(id AS TEXT) AS id FROM refunds WHERE order_id = CAST(? AS INTEGER) ORDER BY id DESC LIMIT 1;\\n\\n-- name: GetRefundTotals :one\\nSELECT CAST(COALESCE(SUM(amount_minor), 0) AS TEXT) AS active_minor,\\n  CAST(COALESCE(SUM(shipping_minor), 0) AS TEXT) AS shipping_minor,\\n  CAST(COALESCE(SUM(shipping_tax_minor), 0) AS TEXT) AS shipping_tax_minor\\nFROM refunds WHERE order_id = CAST(? AS INTEGER) AND state IN ('pending', 'requires_action', 'succeeded');\\n\\n-- name: ListRefundLineQuantities :many\\nSELECT CAST(x.position AS TEXT) AS position, CAST(SUM(x.quantity) AS TEXT) AS quantity\\nFROM refund_lines x JOIN refunds r ON r.id = x.refund_id\\nWHERE x.order_id = CAST(? AS INTEGER) AND r.state IN ('pending', 'requires_action', 'succeeded')\\nGROUP BY x.position ORDER BY x.position;\\n\\n-- name: InsertRefund :execrows\\nINSERT INTO refunds (order_id, state, amount_minor, items_minor, item_tax_minor, shipping_minor, shipping_tax_minor, reason, actor, created_at, updated_at)\\nVALUES (CAST(? AS INTEGER), 'pending', CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertExternalRefund :execrows\\nINSERT INTO refunds (order_id, state, amount_minor, items_minor, item_tax_minor, shipping_minor, shipping_tax_minor, reason, actor, provider_refund_id, failure_reason, created_at, updated_at)\\nVALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER), CAST(? AS INTEGER), 0, 0, 0, 'Created in the Stripe dashboard', 'stripe', ?, ?, CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: InsertRefundLine :execrows\\nINSERT INTO refund_lines (refund_id, order_id, position, quantity, item_minor, tax_minor)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: SetRefundState :execrows\\nUPDATE refunds SET state = ?, provider_refund_id = COALESCE(?, provider_refund_id), failure_reason = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND state = ?;\\n\\n-- name: AddLineCanceled :execrows\\nUPDATE line_fulfillment SET canceled = canceled + CAST(? AS INTEGER)\\nWHERE order_id = CAST(? AS INTEGER) AND position = CAST(? AS INTEGER);\\n\\n-- name: AddLineReturned :execrows\\nUPDATE line_fulfillment SET returned = returned + CAST(? AS INTEGER)\\nWHERE order_id = CAST(? AS INTEGER) AND position = CAST(? AS INTEGER);\\n\\n-- name: InsertRestock :execrows\\nINSERT INTO restocks (order_id, position, quantity, reason, actor, created_at)\\nVALUES (CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), ?, ?, CAST(? AS INTEGER));\\n\",\"email.sql\":\"-- Transactional email and guest order access (docs/commerce.md). int64 columns\\n-- are projected with CAST(col AS TEXT) and bound through CAST(? AS INTEGER).\\n\\n-- name: GetEmailMessage :one\\nSELECT CAST(id AS TEXT) AS id, kind, CAST(order_id AS TEXT) AS order_id, CAST(attempt_id AS TEXT) AS attempt_id, CAST(subject_id AS TEXT) AS subject_id,\\n  CAST(generation AS TEXT) AS generation, state, CAST(attempts AS TEXT) AS attempts, CAST(first_attempt_at AS TEXT) AS first_attempt_at,\\n  CAST(last_attempt_at AS TEXT) AS last_attempt_at, provider_id, last_error, CAST(created_at AS TEXT) AS created_at\\nFROM email_messages WHERE id = CAST(? AS INTEGER);\\n\\n-- name: GetEmailMessageBySubject :one\\nSELECT CAST(id AS TEXT) AS id, CAST(generation AS TEXT) AS generation\\nFROM email_messages WHERE kind = ? AND COALESCE(order_id, attempt_id) = CAST(? AS INTEGER) AND subject_id = CAST(? AS INTEGER);\\n\\n-- name: GetNewestEmailMessage :one\\nSELECT CAST(id AS TEXT) AS id, CAST(generation AS TEXT) AS generation\\nFROM email_messages WHERE kind = ? AND order_id = CAST(? AS INTEGER) ORDER BY id DESC LIMIT 1;\\n\\n-- name: InsertEmailMessage :execrows\\nINSERT INTO email_messages (kind, order_id, attempt_id, subject_id, state, attempts, created_at, updated_at)\\nVALUES (?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), 'queued', 0, CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT DO NOTHING;\\n\\n-- name: BeginEmailAttempt :execrows\\nUPDATE email_messages\\nSET state = 'sending', attempts = attempts + 1, first_attempt_at = COALESCE(first_attempt_at, CAST(? AS INTEGER)), last_attempt_at = CAST(? AS INTEGER), updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND generation = CAST(? AS INTEGER) AND state IN ('queued', 'sending', 'unknown');\\n\\n-- name: SettleEmailMessage :execrows\\nUPDATE email_messages\\nSET state = ?, provider_id = ?, last_error = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND generation = CAST(? AS INTEGER) AND state = 'sending';\\n\\n-- name: ExpireUnknownEmail :execrows\\nUPDATE email_messages\\nSET state = 'unknown', last_error = ?, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND generation = CAST(? AS INTEGER) AND state IN ('sending', 'unknown');\\n\\n-- name: RequeueEmailMessage :execrows\\nUPDATE email_messages\\nSET generation = generation + 1, state = 'queued', attempts = 0, first_attempt_at = NULL, last_attempt_at = NULL, provider_id = NULL, last_error = NULL, updated_at = CAST(? AS INTEGER)\\nWHERE id = CAST(? AS INTEGER) AND order_id = CAST(? AS INTEGER)\\n  AND (state = 'failed' OR (state = 'unknown' AND first_attempt_at <= CAST(? AS INTEGER)));\\n\\n-- name: ListOrderEmails :many\\nSELECT CAST(id AS TEXT) AS id, kind, CAST(generation AS TEXT) AS generation, state, CAST(attempts AS TEXT) AS attempts,\\n  CAST(first_attempt_at AS TEXT) AS first_attempt_at, last_error, CAST(created_at AS TEXT) AS created_at\\nFROM email_messages WHERE order_id = CAST(? AS INTEGER) ORDER BY id DESC LIMIT 100;\\n\\n-- name: GetEmailOrder :one\\nSELECT CAST(o.id AS TEXT) AS id, CAST(o.number AS TEXT) AS number, o.contact_email, o.currency_code,\\n  CAST((SELECT currency_exponent FROM store WHERE id = 1) AS TEXT) AS currency_exponent, (SELECT name FROM store WHERE id = 1) AS shop_name,\\n  o.fulfillment, o.city, o.region, CAST(o.total_minor AS TEXT) AS total_minor\\nFROM orders o WHERE o.id = CAST(? AS INTEGER);\\n\\n-- name: GetEmailAttempt :one\\nSELECT CAST(a.id AS TEXT) AS id, q.contact_email, q.currency_code, CAST((SELECT currency_exponent FROM store WHERE id = 1) AS TEXT) AS currency_exponent,\\n  (SELECT name FROM store WHERE id = 1) AS shop_name, CAST(q.total_minor AS TEXT) AS total_minor\\nFROM checkout_attempts a JOIN quotes q ON q.id = a.quote_id WHERE a.id = CAST(? AS INTEGER);\\n\\n-- name: GetEmailRefund :one\\nSELECT CAST(amount_minor AS TEXT) AS amount_minor FROM refunds WHERE id = CAST(? AS INTEGER) AND order_id = CAST(? AS INTEGER);\\n\\n-- name: GetOrderRevisionById :one\\nSELECT CAST(revision AS TEXT) AS revision FROM orders WHERE id = CAST(? AS INTEGER);\\n\\n-- name: InsertOrderAccess :execrows\\nINSERT INTO order_access (digest, order_id, message_id, created_at, expires_at)\\nVALUES (?, CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER), CAST(? AS INTEGER))\\nON CONFLICT (digest) DO NOTHING;\\n\\n-- name: RevokeOrderAccess :execrows\\nUPDATE order_access SET revoked_at = CAST(? AS INTEGER) WHERE order_id = CAST(? AS INTEGER) AND revoked_at IS NULL;\\n\\n-- name: GetOrderAccessGrant :one\\nSELECT CAST(o.id AS TEXT) AS order_id, CAST(o.number AS TEXT) AS number\\nFROM order_access a JOIN orders o ON o.id = a.order_id\\nWHERE a.digest = ? AND a.revoked_at IS NULL AND a.expires_at > CAST(? AS INTEGER);\\n\\n-- name: GetOrderLookupTarget :one\\nSELECT CAST(id AS TEXT) AS id, email_digest FROM orders WHERE number = CAST(? AS INTEGER);\\n\\n-- name: CountOrderLookups :one\\nSELECT CAST(COUNT(*) AS TEXT) AS n FROM order_lookups WHERE order_number = CAST(? AS INTEGER) AND requested_at > CAST(? AS INTEGER);\\n\\n-- name: InsertOrderLookup :execrows\\nINSERT INTO order_lookups (order_number, requested_at) VALUES (CAST(? AS INTEGER), CAST(? AS INTEGER));\\n\\n-- name: DeleteStaleOrderLookups :execrows\\nDELETE FROM order_lookups WHERE requested_at <= CAST(? AS INTEGER);\\n\"},\"migrations\":[{\"version\":1,\"name\":\"0001_storefront.sql\",\"sql\":\"-- Tenant-local storefront schema. This file is migration 1 and the sqlc source;\\n-- do not maintain a second schema snapshot. See plan.md for application invariants.\\n-- The connection owner enables foreign_keys on EVERY connection before migration.\\n-- Prices are non-negative signed-64-bit minor units in the store's single currency.\\n-- IDs are tenant-local positive integers; public/import IDs are opaque decimal strings.\\n-- Positions are unique and non-negative, not necessarily dense. Availability belongs\\n-- to a variant, never to an option value. All editorial content is plain text.\\n\\nCREATE TABLE store (\\n  id INTEGER PRIMARY KEY CHECK (id = 1),\\n  name TEXT NOT NULL CHECK (length(trim(name)) > 0),\\n  currency_code TEXT NOT NULL CHECK (\\n    length(currency_code) = 3 AND currency_code NOT GLOB '*[^A-Z]*'\\n  ),\\n  currency_exponent INTEGER NOT NULL CHECK (currency_exponent BETWEEN 0 AND 3)\\n) STRICT;\\n\\nCREATE TABLE products (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  handle TEXT NOT NULL UNIQUE CHECK (\\n    length(handle) BETWEEN 1 AND 200 AND handle NOT GLOB '*[^a-z0-9-]*'\\n    AND substr(handle, 1, 1) GLOB '[a-z0-9]'\\n    AND substr(handle, -1, 1) GLOB '[a-z0-9]'\\n  ),\\n  title TEXT NOT NULL CHECK (length(trim(title)) > 0),\\n  vendor TEXT CHECK (vendor IS NULL OR length(trim(vendor)) > 0),\\n  description TEXT NOT NULL DEFAULT '',\\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'archived'))\\n) STRICT;\\n\\n-- Purpose-specific, ordered text panels, not an untyped metafield/EAV system.\\n-- The source's specifications, artist notes, and care instructions become panels.\\nCREATE TABLE product_details (\\n  product_id INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE,\\n  key TEXT NOT NULL CHECK (length(trim(key)) > 0),\\n  title TEXT NOT NULL CHECK (length(trim(title)) > 0),\\n  body TEXT NOT NULL CHECK (length(trim(body)) > 0),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  PRIMARY KEY (product_id, key),\\n  UNIQUE (product_id, position)\\n) STRICT;\\n\\nCREATE TABLE product_options (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  product_id INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE,\\n  name TEXT NOT NULL CHECK (length(trim(name)) > 0),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  UNIQUE (product_id, name),\\n  UNIQUE (product_id, position),\\n  UNIQUE (id, product_id)\\n) STRICT;\\n\\nCREATE TABLE product_option_values (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  option_id INTEGER NOT NULL REFERENCES product_options (id) ON DELETE CASCADE,\\n  value TEXT NOT NULL CHECK (length(trim(value)) > 0),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  UNIQUE (option_id, value),\\n  UNIQUE (option_id, position),\\n  UNIQUE (id, option_id)\\n) STRICT;\\n\\nCREATE TABLE product_variants (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  product_id INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE,\\n  -- Optional editorial label; not identity and not required to be unique.\\n  title TEXT CHECK (title IS NULL OR length(trim(title)) > 0),\\n  price_minor INTEGER NOT NULL CHECK (price_minor >= 0),\\n  available INTEGER NOT NULL CHECK (available IN (0, 1)),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  UNIQUE (product_id, position),\\n  UNIQUE (id, product_id)\\n) STRICT;\\n\\n-- One value per option per variant. Composite FKs prevent attaching another\\n-- product's option or an unrelated option's value, including through UPDATE.\\n-- Exact option coverage and distinct complete combinations are validated by\\n-- the catalog application transaction; ordinary FKs cannot express those rules.\\nCREATE TABLE variant_option_values (\\n  variant_id INTEGER NOT NULL,\\n  product_id INTEGER NOT NULL,\\n  option_id INTEGER NOT NULL,\\n  option_value_id INTEGER NOT NULL,\\n  PRIMARY KEY (variant_id, option_id),\\n  FOREIGN KEY (variant_id, product_id)\\n    REFERENCES product_variants (id, product_id) ON DELETE CASCADE,\\n  FOREIGN KEY (option_id, product_id)\\n    REFERENCES product_options (id, product_id),\\n  FOREIGN KEY (option_value_id, option_id)\\n    REFERENCES product_option_values (id, option_id)\\n) STRICT;\\n\\nCREATE TABLE product_images (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  product_id INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE,\\n  url TEXT NOT NULL CHECK (length(trim(url)) > 0),\\n  alt_text TEXT NOT NULL DEFAULT '',\\n  width INTEGER,\\n  height INTEGER,\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  CHECK (\\n    (width IS NULL AND height IS NULL) OR\\n    (width IS NOT NULL AND height IS NOT NULL AND width > 0 AND height > 0)\\n  ),\\n  UNIQUE (product_id, position)\\n) STRICT;\\n\\nCREATE TABLE collections (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  handle TEXT NOT NULL UNIQUE CHECK (\\n    length(handle) BETWEEN 1 AND 200 AND handle NOT GLOB '*[^a-z0-9-]*'\\n    AND substr(handle, 1, 1) GLOB '[a-z0-9]'\\n    AND substr(handle, -1, 1) GLOB '[a-z0-9]'\\n  ),\\n  title TEXT NOT NULL CHECK (length(trim(title)) > 0),\\n  description TEXT NOT NULL DEFAULT '',\\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'archived'))\\n) STRICT;\\n\\nCREATE TABLE collection_products (\\n  collection_id INTEGER NOT NULL REFERENCES collections (id) ON DELETE CASCADE,\\n  product_id INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE,\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  PRIMARY KEY (collection_id, product_id),\\n  UNIQUE (collection_id, position)\\n) STRICT;\\n\\n-- One anonymous cart per session; no separate cart lifecycle table in v1.\\n-- Store SHA-256 digests of server-generated 256-bit random bearer tokens, not\\n-- the tokens themselves. Resolution is always within the selected tenant DB.\\nCREATE TABLE sessions (\\n  token_hash BLOB PRIMARY KEY CHECK (length(token_hash) = 32),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  expires_at INTEGER NOT NULL CHECK (expires_at > created_at)\\n) STRICT;\\n\\nCREATE TABLE cart_items (\\n  session_hash BLOB NOT NULL REFERENCES sessions (token_hash) ON DELETE CASCADE,\\n  variant_id INTEGER NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 99),\\n  added_at INTEGER NOT NULL CHECK (added_at >= 0),\\n  PRIMARY KEY (session_hash, variant_id)\\n) STRICT;\\n\\n-- Parent-prefix UNIQUE indexes already cover product/options/images ordering.\\n-- These indexes cover the remaining reverse FKs and bounded expiry cleanup.\\nCREATE INDEX idx_variant_values_option ON variant_option_values (option_id, product_id);\\nCREATE INDEX idx_variant_values_value ON variant_option_values (option_value_id, option_id);\\nCREATE INDEX idx_collection_products_product ON collection_products (product_id);\\nCREATE INDEX idx_cart_items_variant ON cart_items (variant_id);\\nCREATE INDEX idx_sessions_expiry ON sessions (expires_at);\\n\",\"checksum\":\"b30c3455df139c5902137577fee3644d97c6d9ad1b9cfdc917aed033bae23ae4\"},{\"version\":2,\"name\":\"0002_catalog_generation.sql\",\"sql\":\"-- Catalog generation (docs/data.md#catalog-generation). One counter that\\n-- changes in the same transaction as any committed change to a catalog\\n-- table, so a server holding an in-memory snapshot of the published catalog\\n-- knows exactly when to reload it. Triggers make this a schema invariant:\\n-- imports, replacements, and direct edits all advance it; sessions and\\n-- carts do not. The counter only increases and cannot be removed.\\nCREATE TABLE catalog_state (\\n  id INTEGER PRIMARY KEY CHECK (id = 1),\\n  generation INTEGER NOT NULL CHECK (generation > 0)\\n) STRICT;\\n\\nINSERT INTO catalog_state (id, generation) VALUES (1, 1);\\n\\nCREATE TRIGGER catalog_state_no_delete BEFORE DELETE ON catalog_state\\nBEGIN\\n  SELECT RAISE(ABORT, 'catalog_state is permanent');\\nEND;\\n\\nCREATE TRIGGER catalog_state_monotonic BEFORE UPDATE ON catalog_state\\nWHEN NEW.id != OLD.id OR NEW.generation <= OLD.generation\\nBEGIN\\n  SELECT RAISE(ABORT, 'catalog generation only increases');\\nEND;\\n\\nCREATE TRIGGER store_insert_advances_generation AFTER INSERT ON store\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER store_update_advances_generation AFTER UPDATE ON store\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER store_delete_advances_generation AFTER DELETE ON store\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER products_insert_advances_generation AFTER INSERT ON products\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER products_update_advances_generation AFTER UPDATE ON products\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER products_delete_advances_generation AFTER DELETE ON products\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_details_insert_advances_generation AFTER INSERT ON product_details\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_details_update_advances_generation AFTER UPDATE ON product_details\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_details_delete_advances_generation AFTER DELETE ON product_details\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_options_insert_advances_generation AFTER INSERT ON product_options\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_options_update_advances_generation AFTER UPDATE ON product_options\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_options_delete_advances_generation AFTER DELETE ON product_options\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_option_values_insert_advances_generation AFTER INSERT ON product_option_values\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_option_values_update_advances_generation AFTER UPDATE ON product_option_values\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_option_values_delete_advances_generation AFTER DELETE ON product_option_values\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_variants_insert_advances_generation AFTER INSERT ON product_variants\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_variants_update_advances_generation AFTER UPDATE ON product_variants\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_variants_delete_advances_generation AFTER DELETE ON product_variants\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER variant_option_values_insert_advances_generation AFTER INSERT ON variant_option_values\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER variant_option_values_update_advances_generation AFTER UPDATE ON variant_option_values\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER variant_option_values_delete_advances_generation AFTER DELETE ON variant_option_values\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_images_insert_advances_generation AFTER INSERT ON product_images\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_images_update_advances_generation AFTER UPDATE ON product_images\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER product_images_delete_advances_generation AFTER DELETE ON product_images\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER collections_insert_advances_generation AFTER INSERT ON collections\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER collections_update_advances_generation AFTER UPDATE ON collections\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER collections_delete_advances_generation AFTER DELETE ON collections\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER collection_products_insert_advances_generation AFTER INSERT ON collection_products\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER collection_products_update_advances_generation AFTER UPDATE ON collection_products\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\nCREATE TRIGGER collection_products_delete_advances_generation AFTER DELETE ON collection_products\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\n\",\"checksum\":\"0b30b643835550f2ffde63909d61aa5e1afd3510aeae457d7fb25cf4011c00fd\"},{\"version\":3,\"name\":\"0003_commerce_core.sql\",\"sql\":\"-- Commerce core: stock, audit, aggregate revisions, and the guards that keep\\n-- commercial records from being orphaned. Stock lives outside the catalog\\n-- tables on purpose: no trigger from 0002 covers inventory_levels,\\n-- stock_adjustments, stock_state, or audit_events, so stock changes never\\n-- advance catalog_state.generation. A variant without an inventory_levels row\\n-- is untracked (unlimited). sellable = on_hand - held - allocated.\\n-- Quantities are bounded at 1,000,000,000 so sums never leave int64.\\n\\nALTER TABLE products ADD COLUMN revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1);\\nALTER TABLE collections ADD COLUMN revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1);\\n\\nCREATE TRIGGER products_revision_monotonic BEFORE UPDATE OF revision ON products\\nWHEN NEW.revision < OLD.revision\\nBEGIN\\n  SELECT RAISE(ABORT, 'revision only increases');\\nEND;\\n\\nCREATE TRIGGER collections_revision_monotonic BEFORE UPDATE OF revision ON collections\\nWHEN NEW.revision < OLD.revision\\nBEGIN\\n  SELECT RAISE(ABORT, 'revision only increases');\\nEND;\\n\\nCREATE TABLE inventory_levels (\\n  variant_id INTEGER PRIMARY KEY REFERENCES product_variants (id),\\n  on_hand INTEGER NOT NULL CHECK (on_hand BETWEEN 0 AND 1000000000),\\n  held INTEGER NOT NULL DEFAULT 0 CHECK (held BETWEEN 0 AND 1000000000),\\n  allocated INTEGER NOT NULL DEFAULT 0 CHECK (allocated BETWEEN 0 AND 1000000000),\\n  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),\\n  CHECK (on_hand - held - allocated >= 0)\\n) STRICT;\\n\\nCREATE INDEX idx_inventory_levels_sold_out ON inventory_levels (variant_id)\\n  WHERE on_hand - held - allocated <= 0;\\n\\nCREATE TRIGGER inventory_levels_variant_immutable BEFORE UPDATE OF variant_id ON inventory_levels\\nWHEN NEW.variant_id != OLD.variant_id\\nBEGIN\\n  SELECT RAISE(ABORT, 'inventory level variant is immutable');\\nEND;\\n\\nCREATE TRIGGER inventory_levels_revision_monotonic BEFORE UPDATE OF revision ON inventory_levels\\nWHEN NEW.revision < OLD.revision\\nBEGIN\\n  SELECT RAISE(ABORT, 'revision only increases');\\nEND;\\n\\n-- Merchant-visible stock history: tracking a variant, adjusting on_hand, and\\n-- restocking. Holds, allocations, and shipments are history of their own\\n-- orders and reservations, not of this table.\\nCREATE TABLE stock_adjustments (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  variant_id INTEGER NOT NULL REFERENCES product_variants (id),\\n  kind TEXT NOT NULL CHECK (kind IN ('track', 'adjust', 'restock')),\\n  delta INTEGER NOT NULL CHECK (\\n    delta BETWEEN -1000000000 AND 1000000000 AND (delta != 0 OR kind = 'track')\\n  ),\\n  on_hand_after INTEGER NOT NULL CHECK (on_hand_after BETWEEN 0 AND 1000000000),\\n  reason TEXT NOT NULL CHECK (length(trim(reason)) > 0 AND length(reason) <= 500),\\n  actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 200),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0)\\n) STRICT;\\n\\nCREATE INDEX idx_stock_adjustments_variant ON stock_adjustments (variant_id, id);\\n\\nCREATE TRIGGER stock_adjustments_no_update BEFORE UPDATE ON stock_adjustments\\nBEGIN\\n  SELECT RAISE(ABORT, 'stock history is append-only');\\nEND;\\n\\nCREATE TRIGGER stock_adjustments_no_delete BEFORE DELETE ON stock_adjustments\\nBEGIN\\n  SELECT RAISE(ABORT, 'stock history is append-only');\\nEND;\\n\\n-- Public availability depends on stock only through whether each variant has\\n-- sellable > 0, so this counter advances only when that flips. A hold that\\n-- does not sell a variant out changes nothing a cache could observe.\\nCREATE TABLE stock_state (\\n  id INTEGER PRIMARY KEY CHECK (id = 1),\\n  version INTEGER NOT NULL CHECK (version > 0)\\n) STRICT;\\n\\nINSERT INTO stock_state (id, version) VALUES (1, 1);\\n\\nCREATE TRIGGER stock_state_no_delete BEFORE DELETE ON stock_state\\nBEGIN\\n  SELECT RAISE(ABORT, 'stock_state is permanent');\\nEND;\\n\\nCREATE TRIGGER stock_state_monotonic BEFORE UPDATE ON stock_state\\nWHEN NEW.id != OLD.id OR NEW.version <= OLD.version\\nBEGIN\\n  SELECT RAISE(ABORT, 'stock state version only increases');\\nEND;\\n\\nCREATE TRIGGER inventory_levels_insert_flips_stock_state AFTER INSERT ON inventory_levels\\nWHEN NEW.on_hand - NEW.held - NEW.allocated <= 0\\nBEGIN\\n  UPDATE stock_state SET version = version + 1 WHERE id = 1;\\nEND;\\n\\nCREATE TRIGGER inventory_levels_update_flips_stock_state AFTER UPDATE ON inventory_levels\\nWHEN (OLD.on_hand - OLD.held - OLD.allocated > 0) != (NEW.on_hand - NEW.held - NEW.allocated > 0)\\nBEGIN\\n  UPDATE stock_state SET version = version + 1 WHERE id = 1;\\nEND;\\n\\nCREATE TRIGGER inventory_levels_delete_flips_stock_state AFTER DELETE ON inventory_levels\\nWHEN OLD.on_hand - OLD.held - OLD.allocated <= 0\\nBEGIN\\n  UPDATE stock_state SET version = version + 1 WHERE id = 1;\\nEND;\\n\\n-- One row per audited effect, written in the same transaction as the effect.\\n-- The action vocabulary is closed in src/commerce; the table constrains only\\n-- its shape so a later migration never has to rebuild it.\\nCREATE TABLE audit_events (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 200),\\n  action TEXT NOT NULL CHECK (\\n    length(action) BETWEEN 3 AND 64 AND action NOT GLOB '*[^a-z._]*'\\n  ),\\n  entity_kind TEXT NOT NULL CHECK (\\n    length(entity_kind) BETWEEN 1 AND 64 AND entity_kind NOT GLOB '*[^a-z_]*'\\n  ),\\n  entity_id TEXT NOT NULL CHECK (length(entity_id) BETWEEN 1 AND 64),\\n  entity_revision INTEGER CHECK (entity_revision IS NULL OR entity_revision >= 1),\\n  summary TEXT NOT NULL CHECK (length(summary) <= 1000),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0)\\n) STRICT;\\n\\nCREATE INDEX idx_audit_events_entity ON audit_events (entity_kind, entity_id, id);\\n\\nCREATE TRIGGER audit_events_no_update BEFORE UPDATE ON audit_events\\nBEGIN\\n  SELECT RAISE(ABORT, 'audit events are append-only');\\nEND;\\n\\nCREATE TRIGGER audit_events_no_delete BEFORE DELETE ON audit_events\\nBEGIN\\n  SELECT RAISE(ABORT, 'audit events are append-only');\\nEND;\\n\\n-- Commercial rows reference catalog rows by plain integers or non-cascading\\n-- keys, so the catalog can never silently delete what a record depends on.\\n-- Every migration that adds a table naming a variant drops and recreates this\\n-- view with its table appended; the guards below never change. Likewise\\n-- currency_bound_rows lists whether any quote or order exists, and is\\n-- recreated by the migration that adds quotes and orders.\\nCREATE VIEW commercial_variant_references (variant_id) AS\\n  SELECT variant_id FROM inventory_levels\\n  UNION ALL\\n  SELECT variant_id FROM stock_adjustments;\\n\\nCREATE VIEW currency_bound_rows (present) AS\\n  SELECT 1 WHERE 0;\\n\\nCREATE TRIGGER product_variants_commercial_reference_guard BEFORE DELETE ON product_variants\\nWHEN EXISTS (SELECT 1 FROM commercial_variant_references WHERE variant_id = OLD.id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'variant is referenced by commercial records; archive it instead');\\nEND;\\n\\nCREATE TRIGGER products_commercial_reference_guard BEFORE DELETE ON products\\nWHEN EXISTS (\\n  SELECT 1 FROM product_variants v\\n  JOIN commercial_variant_references r ON r.variant_id = v.id\\n  WHERE v.product_id = OLD.id\\n)\\nBEGIN\\n  SELECT RAISE(ABORT, 'product is referenced by commercial records; archive it instead');\\nEND;\\n\\nCREATE TRIGGER store_currency_update_guard BEFORE UPDATE OF currency_code, currency_exponent ON store\\nWHEN (NEW.currency_code != OLD.currency_code OR NEW.currency_exponent != OLD.currency_exponent)\\n  AND EXISTS (SELECT 1 FROM currency_bound_rows)\\nBEGIN\\n  SELECT RAISE(ABORT, 'store currency cannot change once quotes or orders exist');\\nEND;\\n\\nCREATE TRIGGER store_currency_delete_guard BEFORE DELETE ON store\\nWHEN EXISTS (SELECT 1 FROM currency_bound_rows)\\nBEGIN\\n  SELECT RAISE(ABORT, 'store cannot be removed once quotes or orders exist');\\nEND;\\n\",\"checksum\":\"959f281a215be3bbe1c52dc511182e1f01f393977d97a96fe2f3239855789d39\"},{\"version\":4,\"name\":\"0004_admin_identity.sql\",\"sql\":\"-- Merchant admin sessions and one-time form tokens. Both tables hold only\\n-- SHA-256 digests of 256-bit bearer tokens, never the tokens. They are\\n-- separate from the shopper sessions table, so a shopper cookie can never\\n-- name an admin session. Neither table is covered by the catalog generation\\n-- triggers, and neither is part of exported tenant state.\\n\\nCREATE TABLE admin_sessions (\\n  token_digest BLOB PRIMARY KEY CHECK (length(token_digest) = 32),\\n  issuer TEXT NOT NULL CHECK (length(issuer) BETWEEN 1 AND 100),\\n  subject TEXT NOT NULL CHECK (length(subject) BETWEEN 1 AND 128),\\n  email TEXT CHECK (email IS NULL OR length(email) BETWEEN 3 AND 254),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  authenticated_at INTEGER NOT NULL CHECK (authenticated_at >= 0),\\n  last_seen_at INTEGER NOT NULL CHECK (last_seen_at >= created_at),\\n  expires_at INTEGER NOT NULL CHECK (expires_at > created_at)\\n) STRICT;\\n\\nCREATE INDEX idx_admin_sessions_principal ON admin_sessions (issuer, subject);\\nCREATE INDEX idx_admin_sessions_expiry ON admin_sessions (expires_at);\\n\\n-- A form token is bound to one session and one purpose (the command and the\\n-- entity it targets) and is deleted in the same transaction as the effect it\\n-- authorizes, so a double submit or a refresh never repeats the effect.\\nCREATE TABLE form_tokens (\\n  token_digest BLOB PRIMARY KEY CHECK (length(token_digest) = 32),\\n  session_digest BLOB NOT NULL REFERENCES admin_sessions (token_digest) ON DELETE CASCADE,\\n  purpose TEXT NOT NULL CHECK (length(purpose) BETWEEN 1 AND 128),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  expires_at INTEGER NOT NULL CHECK (expires_at > created_at)\\n) STRICT;\\n\\nCREATE INDEX idx_form_tokens_session ON form_tokens (session_digest, created_at);\\nCREATE INDEX idx_form_tokens_expiry ON form_tokens (expires_at);\\n\",\"checksum\":\"b2d18e356fd6dc9a2971fbcf2fddd00db8dba4a02b75c31be6d50f005e6cdd89\"},{\"version\":5,\"name\":\"0005_media.sql\",\"sql\":\"-- Media: validated image blobs live outside SQL (an R2 bucket or a data\\n-- directory) under the key m/<id>/<sha256>.<ext>; this table is their index.\\n-- A row is pending until the product image that adopts it is committed, so an\\n-- interrupted upload leaves only a pending row that cleanup removes. The\\n-- table is not covered by the catalog generation triggers: only the\\n-- product_images row that adopts an asset changes what shoppers can see.\\n-- A detail asset names its smaller card rendition in card_id; an image\\n-- uploaded without renditions has none and serves one asset for both.\\n\\nCREATE TABLE media_assets (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  sha256 TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),\\n  bytes INTEGER NOT NULL CHECK (bytes BETWEEN 1 AND 4194304),\\n  width INTEGER NOT NULL CHECK (width BETWEEN 1 AND 4096),\\n  height INTEGER NOT NULL CHECK (height BETWEEN 1 AND 4096),\\n  content_type TEXT NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),\\n  state TEXT NOT NULL CHECK (state IN ('pending', 'ready')),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  ready_at INTEGER CHECK (ready_at IS NULL OR ready_at >= created_at),\\n  card_id INTEGER UNIQUE REFERENCES media_assets (id),\\n  CHECK ((state = 'ready') = (ready_at IS NOT NULL)),\\n  CHECK (card_id IS NULL OR card_id != id)\\n) STRICT;\\n\\nCREATE INDEX idx_media_assets_state ON media_assets (state, created_at);\\n\\nCREATE TRIGGER media_assets_content_immutable BEFORE UPDATE OF id, sha256, bytes, width, height, content_type, created_at ON media_assets\\nBEGIN\\n  SELECT RAISE(ABORT, 'media content is immutable');\\nEND;\\n\\nCREATE TRIGGER media_assets_ready_is_final BEFORE UPDATE ON media_assets\\nWHEN OLD.state = 'ready' AND (NEW.state != 'ready' OR NEW.ready_at IS NOT OLD.ready_at OR NEW.card_id IS NOT OLD.card_id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'ready media is final');\\nEND;\\n\\nCREATE VIEW media_public_paths (media_id, path) AS\\n  SELECT id, '/media/' || id || '/' || sha256 || '.' ||\\n    CASE content_type WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' ELSE 'webp' END\\n  FROM media_assets\\n  WHERE state = 'ready';\\n\\nALTER TABLE product_images ADD COLUMN media_id INTEGER REFERENCES media_assets (id);\\n\\nCREATE INDEX idx_product_images_media ON product_images (media_id) WHERE media_id IS NOT NULL;\\n\\n-- An image that names an asset shows exactly that asset's public path.\\nCREATE TRIGGER product_images_media_path_insert BEFORE INSERT ON product_images\\nWHEN NEW.media_id IS NOT NULL\\n  AND NEW.url IS NOT (SELECT path FROM media_public_paths WHERE media_id = NEW.media_id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'image url must be the public path of its ready media');\\nEND;\\n\\nCREATE TRIGGER product_images_media_path_update BEFORE UPDATE OF url, media_id ON product_images\\nWHEN NEW.media_id IS NOT NULL\\n  AND NEW.url IS NOT (SELECT path FROM media_public_paths WHERE media_id = NEW.media_id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'image url must be the public path of its ready media');\\nEND;\\n\\n-- An import or duplicate that carries a local media path adopts the asset, so\\n-- the asset stays referenced and cleanup never deletes what a product shows.\\nCREATE TRIGGER product_images_adopt_media AFTER INSERT ON product_images\\nWHEN NEW.media_id IS NULL AND NEW.url GLOB '/media/*'\\nBEGIN\\n  UPDATE product_images\\n  SET media_id = (SELECT media_id FROM media_public_paths WHERE path = NEW.url)\\n  WHERE id = NEW.id;\\nEND;\\n\\n-- Every migration that adds a table naming a media asset (order line\\n-- snapshots first) drops and recreates this view with its table appended.\\n-- Cleanup and the delete guard below read only this view, so a reference that\\n-- is missing here is the only way for media to be collected while in use.\\nCREATE VIEW media_references (media_id) AS\\n  SELECT media_id FROM product_images WHERE media_id IS NOT NULL\\n  UNION ALL\\n  SELECT a.card_id FROM media_assets a\\n  JOIN product_images i ON i.media_id = a.id\\n  WHERE a.card_id IS NOT NULL;\\n\\nCREATE TRIGGER media_assets_referenced_guard BEFORE DELETE ON media_assets\\nWHEN EXISTS (SELECT 1 FROM media_references WHERE media_id = OLD.id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'media is referenced and cannot be deleted');\\nEND;\\n\",\"checksum\":\"780f0831ea3c4d114fdc7a65d9e4d2f4a7922cb7ad8c5a20367749c3eb03c9b1\"},{\"version\":6,\"name\":\"0006_checkout.sql\",\"sql\":\"-- Checkout: shop settings, versioned tax and shipping policies, quotes,\\n-- checkout attempts, stock reservations, and durable work items. Commercial\\n-- rows reference catalog rows by plain integers, never by cascading keys, and\\n-- name variants through commercial_variant_references. The store currency\\n-- lives in `store`; it locks once any quote exists (currency_bound_rows).\\n\\nCREATE TABLE shop_settings (\\n  id INTEGER PRIMARY KEY CHECK (id = 1),\\n  checkout_paused INTEGER NOT NULL DEFAULT 0 CHECK (checkout_paused IN (0, 1)),\\n  max_active_holds INTEGER NOT NULL DEFAULT 100 CHECK (max_active_holds BETWEEN 50 AND 500),\\n  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1)\\n) STRICT;\\n\\nINSERT INTO shop_settings (id) VALUES (1);\\n\\nCREATE TRIGGER shop_settings_permanent BEFORE DELETE ON shop_settings\\nBEGIN\\n  SELECT RAISE(ABORT, 'shop_settings is permanent');\\nEND;\\n\\nCREATE TRIGGER shop_settings_revision_monotonic BEFORE UPDATE OF revision ON shop_settings\\nWHEN NEW.revision < OLD.revision\\nBEGIN\\n  SELECT RAISE(ABORT, 'revision only increases');\\nEND;\\n\\n-- Policies are versioned and immutable: a quote records the versions it was\\n-- built from, so a change is a new version. The current policy is the highest\\n-- version.\\nCREATE TABLE tax_policies (\\n  version INTEGER PRIMARY KEY CHECK (version > 0),\\n  mode TEXT NOT NULL CHECK (mode IN ('rate_table', 'no_tax_collected')),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0)\\n) STRICT;\\n\\nCREATE TABLE tax_rates (\\n  version INTEGER NOT NULL REFERENCES tax_policies (version),\\n  region TEXT NOT NULL CHECK (length(region) = 2 AND region NOT GLOB '*[^A-Z]*'),\\n  rate_ppm INTEGER NOT NULL CHECK (rate_ppm BETWEEN 0 AND 1000000),\\n  taxes_lines INTEGER NOT NULL CHECK (taxes_lines IN (0, 1)),\\n  taxes_shipping INTEGER NOT NULL CHECK (taxes_shipping IN (0, 1)),\\n  PRIMARY KEY (version, region)\\n) STRICT;\\n\\nCREATE TABLE shipping_policies (\\n  version INTEGER PRIMARY KEY CHECK (version > 0),\\n  origin_region TEXT NOT NULL CHECK (length(origin_region) = 2 AND origin_region NOT GLOB '*[^A-Z]*'),\\n  free_shipping_threshold_minor INTEGER CHECK (free_shipping_threshold_minor IS NULL OR free_shipping_threshold_minor BETWEEN 0 AND 999999999999),\\n  local_pickup INTEGER NOT NULL CHECK (local_pickup IN (0, 1)),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0)\\n) STRICT;\\n\\nCREATE TABLE shipping_zones (\\n  version INTEGER NOT NULL REFERENCES shipping_policies (version),\\n  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 100),\\n  flat_rate_minor INTEGER NOT NULL CHECK (flat_rate_minor BETWEEN 0 AND 999999999999),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  PRIMARY KEY (version, name),\\n  UNIQUE (version, position)\\n) STRICT;\\n\\nCREATE TABLE shipping_zone_regions (\\n  version INTEGER NOT NULL,\\n  region TEXT NOT NULL CHECK (length(region) = 2 AND region NOT GLOB '*[^A-Z]*'),\\n  zone_name TEXT NOT NULL,\\n  PRIMARY KEY (version, region),\\n  FOREIGN KEY (version, zone_name) REFERENCES shipping_zones (version, name)\\n) STRICT;\\n\\nCREATE TRIGGER tax_policies_immutable BEFORE UPDATE ON tax_policies BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER tax_policies_permanent BEFORE DELETE ON tax_policies BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER tax_rates_immutable BEFORE UPDATE ON tax_rates BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER tax_rates_permanent BEFORE DELETE ON tax_rates BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER shipping_policies_immutable BEFORE UPDATE ON shipping_policies BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER shipping_policies_permanent BEFORE DELETE ON shipping_policies BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER shipping_zones_immutable BEFORE UPDATE ON shipping_zones BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER shipping_zones_permanent BEFORE DELETE ON shipping_zones BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER shipping_zone_regions_immutable BEFORE UPDATE ON shipping_zone_regions BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\nCREATE TRIGGER shipping_zone_regions_permanent BEFORE DELETE ON shipping_zone_regions BEGIN SELECT RAISE(ABORT, 'policies are immutable; add a new version'); END;\\n\\n-- A cart's revision advances on every line change, so a quote can tell that\\n-- the cart it priced is no longer the cart the shopper has. No row means\\n-- revision 0. Cart rows cascade away with their session, so the triggers only\\n-- count a session that still exists.\\nCREATE TABLE cart_revisions (\\n  session_hash BLOB PRIMARY KEY REFERENCES sessions (token_hash) ON DELETE CASCADE,\\n  revision INTEGER NOT NULL CHECK (revision >= 1)\\n) STRICT;\\n\\nCREATE TRIGGER cart_items_insert_revises AFTER INSERT ON cart_items\\nBEGIN\\n  INSERT INTO cart_revisions (session_hash, revision)\\n  SELECT NEW.session_hash, 1 WHERE EXISTS (SELECT 1 FROM sessions WHERE token_hash = NEW.session_hash)\\n  ON CONFLICT (session_hash) DO UPDATE SET revision = revision + 1;\\nEND;\\n\\nCREATE TRIGGER cart_items_update_revises AFTER UPDATE ON cart_items\\nWHEN NEW.quantity != OLD.quantity OR NEW.variant_id != OLD.variant_id\\nBEGIN\\n  INSERT INTO cart_revisions (session_hash, revision)\\n  SELECT NEW.session_hash, 1 WHERE EXISTS (SELECT 1 FROM sessions WHERE token_hash = NEW.session_hash)\\n  ON CONFLICT (session_hash) DO UPDATE SET revision = revision + 1;\\nEND;\\n\\nCREATE TRIGGER cart_items_delete_revises AFTER DELETE ON cart_items\\nBEGIN\\n  INSERT INTO cart_revisions (session_hash, revision)\\n  SELECT OLD.session_hash, 1 WHERE EXISTS (SELECT 1 FROM sessions WHERE token_hash = OLD.session_hash)\\n  ON CONFLICT (session_hash) DO UPDATE SET revision = revision + 1;\\nEND;\\n\\n-- A quote is a priced snapshot of one cart for one destination. Its session\\n-- is a plain digest so ending a session never touches a commercial record.\\nCREATE TABLE quotes (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  ref TEXT NOT NULL UNIQUE CHECK (length(ref) = 32 AND ref NOT GLOB '*[^0-9a-f]*'),\\n  session_hash BLOB NOT NULL CHECK (length(session_hash) = 32),\\n  revision INTEGER NOT NULL CHECK (revision >= 1),\\n  cart_revision INTEGER NOT NULL CHECK (cart_revision >= 0),\\n  currency_code TEXT NOT NULL CHECK (length(currency_code) = 3),\\n  contact_email TEXT NOT NULL CHECK (length(contact_email) BETWEEN 3 AND 254),\\n  fulfillment TEXT NOT NULL CHECK (fulfillment IN ('ship', 'pickup')),\\n  recipient TEXT,\\n  line1 TEXT,\\n  line2 TEXT,\\n  city TEXT,\\n  region TEXT,\\n  postal_code TEXT,\\n  country TEXT,\\n  shipping_zone TEXT,\\n  shipping_free_by_threshold INTEGER NOT NULL CHECK (shipping_free_by_threshold IN (0, 1)),\\n  tax_mode TEXT NOT NULL CHECK (tax_mode IN ('rate_table', 'no_tax_collected')),\\n  merchandise_minor INTEGER NOT NULL CHECK (merchandise_minor >= 0),\\n  shipping_minor INTEGER NOT NULL CHECK (shipping_minor >= 0),\\n  tax_minor INTEGER NOT NULL CHECK (tax_minor >= 0),\\n  total_minor INTEGER NOT NULL CHECK (total_minor >= 0),\\n  tax_policy_version INTEGER NOT NULL REFERENCES tax_policies (version),\\n  shipping_policy_version INTEGER NOT NULL REFERENCES shipping_policies (version),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  expires_at INTEGER NOT NULL,\\n  CHECK (expires_at > created_at),\\n  CHECK (\\n    (fulfillment = 'ship' AND recipient IS NOT NULL AND line1 IS NOT NULL AND city IS NOT NULL\\n      AND region IS NOT NULL AND postal_code IS NOT NULL AND country IS NOT NULL AND shipping_zone IS NOT NULL)\\n    OR (fulfillment = 'pickup' AND recipient IS NULL AND line1 IS NULL AND line2 IS NULL AND city IS NULL\\n      AND region IS NULL AND postal_code IS NULL AND country IS NULL AND shipping_zone IS NULL)\\n  ),\\n  UNIQUE (session_hash, revision)\\n) STRICT;\\n\\nCREATE INDEX idx_quotes_session ON quotes (session_hash, revision);\\n\\nCREATE TABLE quote_lines (\\n  quote_id INTEGER NOT NULL REFERENCES quotes (id),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  product_id INTEGER NOT NULL CHECK (product_id > 0),\\n  variant_id INTEGER NOT NULL CHECK (variant_id > 0),\\n  title TEXT NOT NULL,\\n  variant_label TEXT NOT NULL,\\n  unit_price_minor INTEGER NOT NULL CHECK (unit_price_minor >= 0),\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000000000),\\n  line_total_minor INTEGER NOT NULL CHECK (line_total_minor >= 0),\\n  PRIMARY KEY (quote_id, position)\\n) STRICT;\\n\\nCREATE INDEX idx_quote_lines_variant ON quote_lines (variant_id);\\n\\nCREATE TABLE quote_tax_lines (\\n  quote_id INTEGER NOT NULL REFERENCES quotes (id),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  line_index INTEGER CHECK (line_index IS NULL OR line_index >= 0),\\n  taxable_minor INTEGER NOT NULL CHECK (taxable_minor >= 0),\\n  rate_ppm INTEGER NOT NULL CHECK (rate_ppm BETWEEN 0 AND 1000000),\\n  tax_minor INTEGER NOT NULL CHECK (tax_minor >= 0),\\n  PRIMARY KEY (quote_id, position)\\n) STRICT;\\n\\nCREATE TRIGGER quotes_immutable BEFORE UPDATE ON quotes BEGIN SELECT RAISE(ABORT, 'a quote is a snapshot; request a new one'); END;\\n\\nCREATE TRIGGER quotes_permanent BEFORE DELETE ON quotes BEGIN SELECT RAISE(ABORT, 'quotes are permanent'); END;\\nCREATE TRIGGER quote_lines_immutable BEFORE UPDATE ON quote_lines BEGIN SELECT RAISE(ABORT, 'a quote is a snapshot; request a new one'); END;\\nCREATE TRIGGER quote_lines_permanent BEFORE DELETE ON quote_lines BEGIN SELECT RAISE(ABORT, 'quotes are permanent'); END;\\nCREATE TRIGGER quote_tax_lines_immutable BEFORE UPDATE ON quote_tax_lines BEGIN SELECT RAISE(ABORT, 'a quote is a snapshot; request a new one'); END;\\nCREATE TRIGGER quote_tax_lines_permanent BEFORE DELETE ON quote_tax_lines BEGIN SELECT RAISE(ABORT, 'quotes are permanent'); END;\\n\\n-- One attempt per accepted quote. `state` follows the attempt machine in\\n-- src/commerce/attempt.ts. A hold is pinned while the state is accepted,\\n-- handed_off, superseded, or blocked. `hold_release_after` is the earliest\\n-- time the expiry protocol may release the hold.\\nCREATE TABLE checkout_attempts (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  ref TEXT NOT NULL UNIQUE CHECK (length(ref) = 32 AND ref NOT GLOB '*[^0-9a-f]*'),\\n  quote_id INTEGER NOT NULL UNIQUE REFERENCES quotes (id),\\n  session_hash BLOB NOT NULL CHECK (length(session_hash) = 32),\\n  state TEXT NOT NULL CHECK (state IN ('quoted', 'accepted', 'handed_off', 'authorized', 'expired', 'superseded', 'voided_late', 'blocked')),\\n  accepted_at INTEGER NOT NULL CHECK (accepted_at >= 0),\\n  hold_release_after INTEGER NOT NULL CHECK (hold_release_after > accepted_at),\\n  provider_session_id TEXT,\\n  provider_session_url TEXT,\\n  provider_session_expires_at INTEGER,\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= accepted_at),\\n  CHECK (state != 'handed_off' OR provider_session_id IS NOT NULL)\\n) STRICT;\\n\\nCREATE UNIQUE INDEX idx_checkout_attempts_active_session ON checkout_attempts (session_hash)\\n  WHERE state IN ('accepted', 'handed_off');\\n\\nCREATE INDEX idx_checkout_attempts_pinned ON checkout_attempts (state)\\n  WHERE state IN ('accepted', 'handed_off', 'superseded', 'blocked');\\n\\nCREATE TRIGGER checkout_attempts_identity_immutable BEFORE UPDATE ON checkout_attempts\\nWHEN NEW.id != OLD.id OR NEW.ref != OLD.ref OR NEW.quote_id != OLD.quote_id OR NEW.session_hash != OLD.session_hash OR NEW.accepted_at != OLD.accepted_at\\nBEGIN\\n  SELECT RAISE(ABORT, 'attempt identity is immutable');\\nEND;\\n\\nCREATE TRIGGER checkout_attempts_permanent BEFORE DELETE ON checkout_attempts BEGIN SELECT RAISE(ABORT, 'attempts are permanent'); END;\\n\\n-- One row per variant held for an attempt. `tracked` records whether the\\n-- variant had an inventory row when the hold was placed: an untracked hold\\n-- touched no stock, so releasing it must not either.\\nCREATE TABLE reservations (\\n  attempt_id INTEGER NOT NULL REFERENCES checkout_attempts (id),\\n  variant_id INTEGER NOT NULL CHECK (variant_id > 0),\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000000000),\\n  tracked INTEGER NOT NULL CHECK (tracked IN (0, 1)),\\n  state TEXT NOT NULL CHECK (state IN ('held', 'allocated', 'released')),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  resolved_at INTEGER CHECK (resolved_at IS NULL OR resolved_at >= created_at),\\n  PRIMARY KEY (attempt_id, variant_id),\\n  CHECK ((state = 'held') = (resolved_at IS NULL))\\n) STRICT;\\n\\nCREATE INDEX idx_reservations_variant ON reservations (variant_id);\\n\\nCREATE TRIGGER reservations_identity_immutable BEFORE UPDATE ON reservations\\nWHEN NEW.attempt_id != OLD.attempt_id OR NEW.variant_id != OLD.variant_id OR NEW.quantity != OLD.quantity OR NEW.tracked != OLD.tracked\\nBEGIN\\n  SELECT RAISE(ABORT, 'reservation identity is immutable');\\nEND;\\n\\nCREATE TRIGGER reservations_permanent BEFORE DELETE ON reservations BEGIN SELECT RAISE(ABORT, 'reservations are permanent'); END;\\n\\n-- Durable work, claimed under leases by the job runner. `unique_key` makes\\n-- scheduling idempotent; kind names are closed in src/commerce, so the table\\n-- constrains only their shape.\\nCREATE TABLE work_items (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  kind TEXT NOT NULL CHECK (length(kind) BETWEEN 3 AND 64 AND kind NOT GLOB '*[^a-z_]*'),\\n  unique_key TEXT NOT NULL UNIQUE CHECK (length(unique_key) BETWEEN 1 AND 200),\\n  payload TEXT NOT NULL CHECK (length(payload) <= 2000),\\n  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'leased', 'succeeded', 'dead')),\\n  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),\\n  next_run_at INTEGER NOT NULL CHECK (next_run_at >= 0),\\n  lease_owner TEXT,\\n  lease_expires_at INTEGER,\\n  failure_class TEXT CHECK (failure_class IS NULL OR failure_class IN ('retryable', 'permanent', 'blocked')),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= created_at),\\n  CHECK ((state = 'leased') = (lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL))\\n) STRICT;\\n\\nCREATE INDEX idx_work_items_due ON work_items (next_run_at) WHERE state = 'pending';\\n\\nCREATE TRIGGER work_items_identity_immutable BEFORE UPDATE ON work_items\\nWHEN NEW.id != OLD.id OR NEW.kind != OLD.kind OR NEW.unique_key != OLD.unique_key OR NEW.created_at != OLD.created_at\\nBEGIN\\n  SELECT RAISE(ABORT, 'work item identity is immutable');\\nEND;\\n\\nDROP VIEW commercial_variant_references;\\nCREATE VIEW commercial_variant_references (variant_id) AS\\n  SELECT variant_id FROM inventory_levels\\n  UNION ALL\\n  SELECT variant_id FROM stock_adjustments\\n  UNION ALL\\n  SELECT variant_id FROM quote_lines\\n  UNION ALL\\n  SELECT variant_id FROM reservations;\\n\\nDROP VIEW currency_bound_rows;\\nCREATE VIEW currency_bound_rows (present) AS\\n  SELECT 1 FROM quotes LIMIT 1;\\n\",\"checksum\":\"b51d1ce5fb213c134eeaf1dc2351e2958d98bcc51649026a6135e436e637f0af\"},{\"version\":7,\"name\":\"0007_inbox.sql\",\"sql\":\"-- Inbox and operations: provider webhook events received once each, and the\\n-- ledger of external financial operations. A work item records its last\\n-- failure so a dead item is diagnosable without logs.\\n\\nALTER TABLE work_items ADD COLUMN last_error TEXT CHECK (last_error IS NULL OR length(last_error) <= 500);\\n\\nCREATE TABLE provider_events (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  stripe_event_id TEXT NOT NULL UNIQUE CHECK (length(stripe_event_id) BETWEEN 5 AND 255 AND stripe_event_id NOT GLOB '*[^A-Za-z0-9_]*'),\\n  event_type TEXT NOT NULL CHECK (length(event_type) BETWEEN 1 AND 100),\\n  object_id TEXT NOT NULL CHECK (length(object_id) BETWEEN 1 AND 255),\\n  event_created_at INTEGER NOT NULL CHECK (event_created_at >= 0),\\n  received_at INTEGER NOT NULL CHECK (received_at >= 0),\\n  processed_at INTEGER CHECK (processed_at IS NULL OR processed_at >= received_at),\\n  raw_body TEXT CHECK (raw_body IS NULL OR length(CAST(raw_body AS BLOB)) <= 524288),\\n  raw_purged_at INTEGER CHECK (raw_purged_at IS NULL OR raw_purged_at >= received_at),\\n  CHECK ((raw_body IS NULL) = (raw_purged_at IS NOT NULL))\\n) STRICT;\\n\\nCREATE INDEX idx_provider_events_raw ON provider_events (received_at) WHERE raw_body IS NOT NULL;\\n\\nCREATE TRIGGER provider_events_identity_immutable BEFORE UPDATE ON provider_events\\nWHEN NEW.id != OLD.id OR NEW.stripe_event_id != OLD.stripe_event_id OR NEW.event_type != OLD.event_type OR NEW.object_id != OLD.object_id\\n  OR NEW.event_created_at != OLD.event_created_at OR NEW.received_at != OLD.received_at\\n  OR (NEW.raw_body IS NOT OLD.raw_body AND NEW.raw_body IS NOT NULL)\\nBEGIN\\n  SELECT RAISE(ABORT, 'provider event identity is immutable');\\nEND;\\n\\nCREATE TRIGGER provider_events_permanent BEFORE DELETE ON provider_events\\nBEGIN\\n  SELECT RAISE(ABORT, 'provider events are never deleted');\\nEND;\\n\\nCREATE TABLE provider_operations (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  kind TEXT NOT NULL CHECK (kind IN ('create_session', 'capture', 'cancel_pi', 'expire_session', 'refund')),\\n  subject_id TEXT NOT NULL CHECK (length(subject_id) BETWEEN 1 AND 200),\\n  idempotency_key TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) BETWEEN 1 AND 255),\\n  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'in_flight', 'succeeded', 'failed', 'unknown', 'blocked')),\\n  provider_object_id TEXT CHECK (provider_object_id IS NULL OR length(provider_object_id) BETWEEN 1 AND 255),\\n  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),\\n  last_error TEXT CHECK (last_error IS NULL OR length(last_error) <= 500),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= created_at),\\n  UNIQUE (kind, subject_id)\\n) STRICT;\\n\\nCREATE TRIGGER provider_operations_identity_immutable BEFORE UPDATE ON provider_operations\\nWHEN NEW.id != OLD.id OR NEW.kind != OLD.kind OR NEW.subject_id != OLD.subject_id OR NEW.idempotency_key != OLD.idempotency_key OR NEW.created_at != OLD.created_at\\nBEGIN\\n  SELECT RAISE(ABORT, 'provider operation identity is immutable');\\nEND;\\n\\nCREATE TRIGGER provider_operations_permanent BEFORE DELETE ON provider_operations\\nBEGIN\\n  SELECT RAISE(ABORT, 'provider operations are never deleted');\\nEND;\\n\",\"checksum\":\"221d7de9249e201a1f03125d83287cb46e0ecd79980c33bc4a91e3f430405fcc\"},{\"version\":8,\"name\":\"0008_payments.sql\",\"sql\":\"-- Orders, their line snapshots, payments, and order exceptions. An order\\n-- exists only from a verified authorization with an allocation, so each one\\n-- belongs to exactly one checkout attempt and one PaymentIntent. Orders copy\\n-- what the customer approved from the accepted quote and name catalog rows by\\n-- plain integers with no foreign key, so later catalog edits never change or\\n-- remove an order. Order lines join commercial_variant_references and\\n-- media_references, and orders join currency_bound_rows.\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  number INTEGER NOT NULL UNIQUE CHECK (number > 0),\\n  attempt_id INTEGER NOT NULL UNIQUE REFERENCES checkout_attempts (id),\\n  quote_id INTEGER NOT NULL UNIQUE REFERENCES quotes (id),\\n  currency_code TEXT NOT NULL CHECK (length(currency_code) = 3),\\n  contact_email TEXT NOT NULL CHECK (length(contact_email) BETWEEN 3 AND 254),\\n  fulfillment TEXT NOT NULL CHECK (fulfillment IN ('ship', 'pickup')),\\n  recipient TEXT,\\n  line1 TEXT,\\n  line2 TEXT,\\n  city TEXT,\\n  region TEXT,\\n  postal_code TEXT,\\n  country TEXT,\\n  shipping_zone TEXT,\\n  shipping_free_by_threshold INTEGER NOT NULL CHECK (shipping_free_by_threshold IN (0, 1)),\\n  tax_mode TEXT NOT NULL CHECK (tax_mode IN ('rate_table', 'no_tax_collected')),\\n  merchandise_minor INTEGER NOT NULL CHECK (merchandise_minor >= 0),\\n  shipping_minor INTEGER NOT NULL CHECK (shipping_minor >= 0),\\n  shipping_tax_minor INTEGER NOT NULL CHECK (shipping_tax_minor >= 0),\\n  shipping_tax_rate_ppm INTEGER NOT NULL CHECK (shipping_tax_rate_ppm BETWEEN 0 AND 1000000),\\n  tax_minor INTEGER NOT NULL CHECK (tax_minor >= shipping_tax_minor),\\n  total_minor INTEGER NOT NULL CHECK (total_minor = merchandise_minor + shipping_minor + tax_minor),\\n  tax_policy_version INTEGER NOT NULL CHECK (tax_policy_version > 0),\\n  shipping_policy_version INTEGER NOT NULL CHECK (shipping_policy_version > 0),\\n  allocation TEXT NOT NULL CHECK (allocation IN ('hold', 'late')),\\n  placed_at INTEGER NOT NULL CHECK (placed_at >= 0),\\n  CHECK (\\n    (fulfillment = 'ship' AND recipient IS NOT NULL AND line1 IS NOT NULL AND city IS NOT NULL\\n      AND region IS NOT NULL AND postal_code IS NOT NULL AND country IS NOT NULL AND shipping_zone IS NOT NULL)\\n    OR (fulfillment = 'pickup' AND recipient IS NULL AND line1 IS NULL AND line2 IS NULL AND city IS NULL\\n      AND region IS NULL AND postal_code IS NULL AND country IS NULL AND shipping_zone IS NULL)\\n  )\\n) STRICT;\\n\\n-- The snapshot columns never change; later migrations may add mutable\\n-- columns, which this trigger leaves alone.\\nCREATE TRIGGER orders_snapshot_immutable BEFORE UPDATE OF\\n  id, number, attempt_id, quote_id, currency_code, fulfillment, shipping_zone, shipping_free_by_threshold, tax_mode,\\n  merchandise_minor, shipping_minor, shipping_tax_minor, shipping_tax_rate_ppm, tax_minor, total_minor,\\n  tax_policy_version, shipping_policy_version, allocation, placed_at\\nON orders\\nBEGIN\\n  SELECT RAISE(ABORT, 'an order is a snapshot of what the customer approved');\\nEND;\\n\\nCREATE TRIGGER orders_permanent BEFORE DELETE ON orders BEGIN SELECT RAISE(ABORT, 'orders are permanent'); END;\\n\\nCREATE TABLE order_lines (\\n  order_id INTEGER NOT NULL REFERENCES orders (id),\\n  position INTEGER NOT NULL CHECK (position >= 0),\\n  product_id INTEGER NOT NULL CHECK (product_id > 0),\\n  variant_id INTEGER NOT NULL CHECK (variant_id > 0),\\n  title TEXT NOT NULL,\\n  variant_label TEXT NOT NULL,\\n  unit_price_minor INTEGER NOT NULL CHECK (unit_price_minor >= 0),\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000000000),\\n  line_total_minor INTEGER NOT NULL CHECK (line_total_minor >= 0),\\n  taxable_minor INTEGER NOT NULL CHECK (taxable_minor >= 0),\\n  tax_rate_ppm INTEGER NOT NULL CHECK (tax_rate_ppm BETWEEN 0 AND 1000000),\\n  tax_minor INTEGER NOT NULL CHECK (tax_minor >= 0),\\n  image_media_id INTEGER CHECK (image_media_id IS NULL OR image_media_id > 0),\\n  PRIMARY KEY (order_id, position)\\n) STRICT;\\n\\nCREATE INDEX idx_order_lines_variant ON order_lines (variant_id);\\nCREATE INDEX idx_order_lines_media ON order_lines (image_media_id) WHERE image_media_id IS NOT NULL;\\n\\nCREATE TRIGGER order_lines_immutable BEFORE UPDATE ON order_lines BEGIN SELECT RAISE(ABORT, 'an order is a snapshot of what the customer approved'); END;\\nCREATE TRIGGER order_lines_permanent BEFORE DELETE ON order_lines BEGIN SELECT RAISE(ABORT, 'orders are permanent'); END;\\n\\n-- One payment per order and one order per PaymentIntent. `state` follows the\\n-- payment machine in src/commerce/payment.ts. Refund amounts live on refund\\n-- rows, not here.\\nCREATE TABLE payments (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  order_id INTEGER NOT NULL UNIQUE REFERENCES orders (id),\\n  payment_intent_id TEXT NOT NULL UNIQUE CHECK (length(payment_intent_id) BETWEEN 1 AND 255 AND payment_intent_id NOT GLOB '*[^A-Za-z0-9_]*'),\\n  state TEXT NOT NULL CHECK (state IN ('authorized', 'in_review', 'capture_pending', 'capture_unknown', 'captured', 'void_unknown', 'voided')),\\n  currency_code TEXT NOT NULL CHECK (length(currency_code) = 3),\\n  amount_authorized_minor INTEGER NOT NULL CHECK (amount_authorized_minor > 0),\\n  amount_captured_minor INTEGER NOT NULL DEFAULT 0 CHECK (amount_captured_minor BETWEEN 0 AND amount_authorized_minor),\\n  review_id TEXT CHECK (review_id IS NULL OR length(review_id) BETWEEN 1 AND 255),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= created_at),\\n  CHECK ((state = 'captured') = (amount_captured_minor > 0))\\n) STRICT;\\n\\nCREATE INDEX idx_payments_open ON payments (state) WHERE state NOT IN ('captured', 'voided');\\n\\nCREATE TRIGGER payments_identity_immutable BEFORE UPDATE ON payments\\nWHEN NEW.id != OLD.id OR NEW.order_id != OLD.order_id OR NEW.payment_intent_id != OLD.payment_intent_id OR NEW.currency_code != OLD.currency_code\\n  OR NEW.amount_authorized_minor != OLD.amount_authorized_minor OR NEW.created_at != OLD.created_at\\nBEGIN\\n  SELECT RAISE(ABORT, 'payment identity is immutable');\\nEND;\\n\\nCREATE TRIGGER payments_final BEFORE UPDATE OF state ON payments\\nWHEN OLD.state IN ('captured', 'voided') AND NEW.state != OLD.state\\nBEGIN\\n  SELECT RAISE(ABORT, 'a captured or voided payment is final');\\nEND;\\n\\nCREATE TRIGGER payments_permanent BEFORE DELETE ON payments BEGIN SELECT RAISE(ABORT, 'payments are permanent'); END;\\n\\n-- Problems the merchant or operator must see: Radar reviews, disputes, early\\n-- fraud warnings, a PaymentIntent that failed verification, a provider state\\n-- Nanoshop cannot map, and a blocked operation. Every one belongs to an\\n-- attempt; those raised after an order exists name it too. Adjudication stays\\n-- in the Stripe dashboard; these rows only make the problem visible.\\nCREATE TABLE order_exceptions (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  attempt_id INTEGER NOT NULL REFERENCES checkout_attempts (id),\\n  order_id INTEGER REFERENCES orders (id),\\n  kind TEXT NOT NULL CHECK (kind IN ('review', 'dispute', 'early_fraud_warning', 'payment_mismatch', 'payment_canceled', 'unmapped_state', 'operation_blocked')),\\n  provider_object_id TEXT NOT NULL CHECK (length(provider_object_id) BETWEEN 1 AND 255),\\n  state TEXT NOT NULL CHECK (state IN ('open', 'closed')),\\n  detail TEXT NOT NULL CHECK (length(detail) <= 500),\\n  opened_at INTEGER NOT NULL CHECK (opened_at >= 0),\\n  closed_at INTEGER CHECK (closed_at IS NULL OR closed_at >= opened_at),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= opened_at),\\n  CHECK ((state = 'closed') = (closed_at IS NOT NULL)),\\n  UNIQUE (kind, provider_object_id)\\n) STRICT;\\n\\nCREATE INDEX idx_order_exceptions_order ON order_exceptions (order_id, state);\\nCREATE INDEX idx_order_exceptions_open ON order_exceptions (state, opened_at) WHERE state = 'open';\\n\\nCREATE TRIGGER order_exceptions_identity_immutable BEFORE UPDATE ON order_exceptions\\nWHEN NEW.id != OLD.id OR NEW.attempt_id != OLD.attempt_id OR NEW.kind != OLD.kind OR NEW.provider_object_id != OLD.provider_object_id\\n  OR NEW.opened_at != OLD.opened_at OR (OLD.order_id IS NOT NULL AND NEW.order_id IS NOT OLD.order_id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'order exception identity is immutable');\\nEND;\\n\\nCREATE TRIGGER order_exceptions_permanent BEFORE DELETE ON order_exceptions BEGIN SELECT RAISE(ABORT, 'order exceptions are permanent'); END;\\n\\n-- A Durable Object's SQLite accepts at most five terms in one compound\\n-- SELECT, so these views group their sources: a later migration appends a\\n-- group (or a term to a group with room) instead of a sixth flat term.\\nDROP VIEW commercial_variant_references;\\nCREATE VIEW commercial_variant_references (variant_id) AS\\n  SELECT variant_id FROM (\\n    SELECT variant_id FROM inventory_levels\\n    UNION ALL\\n    SELECT variant_id FROM stock_adjustments\\n  )\\n  UNION ALL\\n  SELECT variant_id FROM (\\n    SELECT variant_id FROM quote_lines\\n    UNION ALL\\n    SELECT variant_id FROM reservations\\n    UNION ALL\\n    SELECT variant_id FROM order_lines\\n  );\\n\\nDROP VIEW media_references;\\nCREATE VIEW media_references (media_id) AS\\n  SELECT media_id FROM (\\n    SELECT media_id FROM product_images WHERE media_id IS NOT NULL\\n    UNION ALL\\n    SELECT a.card_id FROM media_assets a\\n    JOIN product_images i ON i.media_id = a.id\\n    WHERE a.card_id IS NOT NULL\\n  )\\n  UNION ALL\\n  SELECT media_id FROM (\\n    SELECT image_media_id AS media_id FROM order_lines WHERE image_media_id IS NOT NULL\\n    UNION ALL\\n    SELECT a.card_id FROM media_assets a\\n    JOIN order_lines l ON l.image_media_id = a.id\\n    WHERE a.card_id IS NOT NULL\\n  );\\n\\nDROP VIEW currency_bound_rows;\\nCREATE VIEW currency_bound_rows (present) AS\\n  SELECT 1 FROM quotes\\n  UNION ALL\\n  SELECT 1 FROM orders;\\n\",\"checksum\":\"7114fb6657313763af4f3f7068b04dd8ae93f516f190eaa55800fcbcacf67522\"},{\"version\":9,\"name\":\"0009_fulfillment.sql\",\"sql\":\"-- Fulfillment, refunds, restocks, and merchant notes. Every table names an\\n-- order or an order line by plain integers, so none of them touches the\\n-- variant or media guard views: those already join order_lines.\\n--\\n-- line_fulfillment holds the running per-line quantities (shipped, canceled,\\n-- returned) that src/commerce/fulfillment.ts decides over. fulfillments and\\n-- fulfillment_lines record each shipment. Refunds and restocks are separate\\n-- decisions: refund rows carry the money, restock rows carry the units that\\n-- returned to on_hand.\\n\\nALTER TABLE orders ADD COLUMN revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1);\\nALTER TABLE orders ADD COLUMN fulfillment_status TEXT NOT NULL DEFAULT 'unfulfilled'\\n  CHECK (fulfillment_status IN ('unfulfilled', 'partially_fulfilled', 'fulfilled', 'canceled'));\\nALTER TABLE orders ADD COLUMN email_digest BLOB CHECK (email_digest IS NULL OR length(email_digest) = 32);\\n\\nCREATE TRIGGER orders_revision_monotonic BEFORE UPDATE OF revision ON orders\\nWHEN NEW.revision < OLD.revision\\nBEGIN\\n  SELECT RAISE(ABORT, 'revision only increases');\\nEND;\\n\\nCREATE INDEX idx_orders_fulfillment_status ON orders (fulfillment_status, number);\\nCREATE INDEX idx_orders_email_digest ON orders (email_digest, number) WHERE email_digest IS NOT NULL;\\n\\n-- The key that turns a customer email into the exact-match search digest on\\n-- orders.email_digest. One row, written here, never changed.\\nCREATE TABLE order_search_key (\\n  id INTEGER PRIMARY KEY CHECK (id = 1),\\n  key BLOB NOT NULL CHECK (length(key) = 32)\\n) STRICT;\\n\\nINSERT INTO order_search_key (id, key) VALUES (1, randomblob(32));\\n\\nCREATE TRIGGER order_search_key_fixed BEFORE UPDATE ON order_search_key BEGIN SELECT RAISE(ABORT, 'the order search key never changes'); END;\\nCREATE TRIGGER order_search_key_permanent BEFORE DELETE ON order_search_key BEGIN SELECT RAISE(ABORT, 'the order search key never changes'); END;\\n\\nCREATE TABLE line_fulfillment (\\n  order_id INTEGER NOT NULL,\\n  position INTEGER NOT NULL,\\n  shipped INTEGER NOT NULL DEFAULT 0 CHECK (shipped BETWEEN 0 AND 1000000000),\\n  canceled INTEGER NOT NULL DEFAULT 0 CHECK (canceled BETWEEN 0 AND 1000000000),\\n  returned INTEGER NOT NULL DEFAULT 0 CHECK (returned BETWEEN 0 AND 1000000000),\\n  PRIMARY KEY (order_id, position),\\n  FOREIGN KEY (order_id, position) REFERENCES order_lines (order_id, position),\\n  CHECK (returned <= shipped)\\n) STRICT;\\n\\nINSERT INTO line_fulfillment (order_id, position) SELECT order_id, position FROM order_lines;\\n\\nCREATE TRIGGER order_lines_start_fulfillment AFTER INSERT ON order_lines\\nBEGIN\\n  INSERT INTO line_fulfillment (order_id, position) VALUES (NEW.order_id, NEW.position);\\nEND;\\n\\nCREATE TRIGGER line_fulfillment_bounds BEFORE UPDATE ON line_fulfillment\\nWHEN NEW.order_id != OLD.order_id OR NEW.position != OLD.position\\n  OR NEW.shipped < OLD.shipped OR NEW.canceled < OLD.canceled OR NEW.returned < OLD.returned\\n  OR NEW.shipped + NEW.canceled > (SELECT quantity FROM order_lines WHERE order_id = NEW.order_id AND position = NEW.position)\\nBEGIN\\n  SELECT RAISE(ABORT, 'line fulfillment only grows and never exceeds the quantity ordered');\\nEND;\\n\\nCREATE TRIGGER line_fulfillment_permanent BEFORE DELETE ON line_fulfillment BEGIN SELECT RAISE(ABORT, 'fulfillment records are permanent'); END;\\n\\n-- Mirrors fulfillmentStatus() in src/commerce/fulfillment.ts; tests compare\\n-- the two.\\nCREATE TRIGGER line_fulfillment_status AFTER UPDATE ON line_fulfillment\\nBEGIN\\n  UPDATE orders SET fulfillment_status = (\\n    SELECT CASE\\n      WHEN SUM(f.canceled) = SUM(l.quantity) THEN 'canceled'\\n      WHEN SUM(f.shipped) = 0 THEN 'unfulfilled'\\n      WHEN SUM(f.shipped) + SUM(f.canceled) = SUM(l.quantity) THEN 'fulfilled'\\n      ELSE 'partially_fulfilled'\\n    END\\n    FROM line_fulfillment f JOIN order_lines l ON l.order_id = f.order_id AND l.position = f.position\\n    WHERE f.order_id = NEW.order_id\\n  )\\n  WHERE id = NEW.order_id;\\nEND;\\n\\nCREATE TABLE fulfillments (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  order_id INTEGER NOT NULL REFERENCES orders (id),\\n  sequence INTEGER NOT NULL CHECK (sequence >= 1),\\n  carrier TEXT NOT NULL CHECK (length(carrier) BETWEEN 1 AND 60),\\n  tracking_number TEXT CHECK (tracking_number IS NULL OR length(tracking_number) BETWEEN 1 AND 100),\\n  tracking_url TEXT CHECK (\\n    tracking_url IS NULL\\n    OR (length(tracking_url) BETWEEN 9 AND 500 AND (tracking_url GLOB 'https://*' OR tracking_url GLOB 'http://*') AND tracking_url NOT GLOB '*[^!-~]*')\\n  ),\\n  actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 200),\\n  shipped_at INTEGER NOT NULL CHECK (shipped_at >= 0),\\n  UNIQUE (order_id, sequence),\\n  UNIQUE (id, order_id)\\n) STRICT;\\n\\nCREATE TRIGGER fulfillments_require_capture BEFORE INSERT ON fulfillments\\nWHEN NOT EXISTS (SELECT 1 FROM payments WHERE order_id = NEW.order_id AND state = 'captured')\\n  OR EXISTS (SELECT 1 FROM order_exceptions WHERE order_id = NEW.order_id AND kind = 'review' AND state = 'open')\\nBEGIN\\n  SELECT RAISE(ABORT, 'an order ships only after capture and with no open review');\\nEND;\\n\\nCREATE TRIGGER fulfillments_append_only BEFORE UPDATE ON fulfillments BEGIN SELECT RAISE(ABORT, 'fulfillments are append-only'); END;\\nCREATE TRIGGER fulfillments_permanent BEFORE DELETE ON fulfillments BEGIN SELECT RAISE(ABORT, 'fulfillments are permanent'); END;\\n\\nCREATE TABLE fulfillment_lines (\\n  fulfillment_id INTEGER NOT NULL,\\n  order_id INTEGER NOT NULL,\\n  position INTEGER NOT NULL,\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000000000),\\n  PRIMARY KEY (fulfillment_id, position),\\n  FOREIGN KEY (fulfillment_id, order_id) REFERENCES fulfillments (id, order_id),\\n  FOREIGN KEY (order_id, position) REFERENCES order_lines (order_id, position)\\n) STRICT;\\n\\nCREATE INDEX idx_fulfillment_lines_line ON fulfillment_lines (order_id, position);\\n\\nCREATE TRIGGER fulfillment_lines_append_only BEFORE UPDATE ON fulfillment_lines BEGIN SELECT RAISE(ABORT, 'fulfillments are append-only'); END;\\nCREATE TRIGGER fulfillment_lines_permanent BEFORE DELETE ON fulfillment_lines BEGIN SELECT RAISE(ABORT, 'fulfillments are permanent'); END;\\n\\nCREATE TABLE order_notes (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  order_id INTEGER NOT NULL REFERENCES orders (id),\\n  body TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 2000),\\n  actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 200),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0)\\n) STRICT;\\n\\nCREATE INDEX idx_order_notes_order ON order_notes (order_id, id);\\n\\nCREATE TRIGGER order_notes_append_only BEFORE UPDATE ON order_notes BEGIN SELECT RAISE(ABORT, 'order notes are append-only'); END;\\nCREATE TRIGGER order_notes_permanent BEFORE DELETE ON order_notes BEGIN SELECT RAISE(ABORT, 'order notes are permanent'); END;\\n\\n-- A refund's local id is the subject of its provider_operations row. The\\n-- states are Stripe's. Pending, requires_action, and succeeded rows count\\n-- against the captured amount; failed and canceled rows stay visible and\\n-- count for nothing, and a retry is a new row.\\nCREATE TABLE refunds (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  order_id INTEGER NOT NULL REFERENCES orders (id),\\n  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'requires_action', 'succeeded', 'failed', 'canceled')),\\n  amount_minor INTEGER NOT NULL CHECK (amount_minor BETWEEN 1 AND 999999999999),\\n  items_minor INTEGER NOT NULL CHECK (items_minor >= 0),\\n  item_tax_minor INTEGER NOT NULL CHECK (item_tax_minor >= 0),\\n  shipping_minor INTEGER NOT NULL CHECK (shipping_minor >= 0),\\n  shipping_tax_minor INTEGER NOT NULL CHECK (shipping_tax_minor >= 0),\\n  reason TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 500),\\n  actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 200),\\n  provider_refund_id TEXT UNIQUE CHECK (provider_refund_id IS NULL OR (length(provider_refund_id) BETWEEN 1 AND 255 AND provider_refund_id NOT GLOB '*[^A-Za-z0-9_]*')),\\n  failure_reason TEXT CHECK (failure_reason IS NULL OR length(failure_reason) <= 500),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= created_at),\\n  CHECK (amount_minor = items_minor + item_tax_minor + shipping_minor + shipping_tax_minor),\\n  UNIQUE (id, order_id)\\n) STRICT;\\n\\nCREATE INDEX idx_refunds_order ON refunds (order_id, id);\\n\\nCREATE TRIGGER refunds_within_captured BEFORE INSERT ON refunds\\nWHEN NEW.state IN ('pending', 'requires_action', 'succeeded')\\n  AND NEW.amount_minor > COALESCE((SELECT amount_captured_minor FROM payments WHERE order_id = NEW.order_id AND state = 'captured'), 0)\\n    - COALESCE((SELECT SUM(amount_minor) FROM refunds WHERE order_id = NEW.order_id AND state IN ('pending', 'requires_action', 'succeeded')), 0)\\nBEGIN\\n  SELECT RAISE(ABORT, 'refunds exceed the captured amount');\\nEND;\\n\\nCREATE TRIGGER refunds_within_shipping BEFORE INSERT ON refunds\\nWHEN NEW.state IN ('pending', 'requires_action', 'succeeded')\\n  AND (\\n    NEW.shipping_minor + COALESCE((SELECT SUM(shipping_minor) FROM refunds WHERE order_id = NEW.order_id AND state IN ('pending', 'requires_action', 'succeeded')), 0)\\n      > (SELECT shipping_minor FROM orders WHERE id = NEW.order_id)\\n    OR NEW.shipping_tax_minor + COALESCE((SELECT SUM(shipping_tax_minor) FROM refunds WHERE order_id = NEW.order_id AND state IN ('pending', 'requires_action', 'succeeded')), 0)\\n      > (SELECT shipping_tax_minor FROM orders WHERE id = NEW.order_id)\\n  )\\nBEGIN\\n  SELECT RAISE(ABORT, 'refunds exceed the shipping charged');\\nEND;\\n\\nCREATE TRIGGER refunds_identity_immutable BEFORE UPDATE ON refunds\\nWHEN NEW.id != OLD.id OR NEW.order_id != OLD.order_id OR NEW.amount_minor != OLD.amount_minor OR NEW.items_minor != OLD.items_minor\\n  OR NEW.item_tax_minor != OLD.item_tax_minor OR NEW.shipping_minor != OLD.shipping_minor OR NEW.shipping_tax_minor != OLD.shipping_tax_minor\\n  OR NEW.reason != OLD.reason OR NEW.actor != OLD.actor OR NEW.created_at != OLD.created_at\\nBEGIN\\n  SELECT RAISE(ABORT, 'a refund''s amounts and identity are immutable');\\nEND;\\n\\nCREATE TRIGGER refunds_state_machine BEFORE UPDATE OF state ON refunds\\nWHEN (OLD.state IN ('failed', 'canceled') AND NEW.state != OLD.state)\\n  OR (OLD.state = 'succeeded' AND NEW.state NOT IN ('succeeded', 'failed'))\\nBEGIN\\n  SELECT RAISE(ABORT, 'refund state cannot move backwards');\\nEND;\\n\\nCREATE TRIGGER refunds_permanent BEFORE DELETE ON refunds BEGIN SELECT RAISE(ABORT, 'refunds are permanent'); END;\\n\\nCREATE TABLE refund_lines (\\n  refund_id INTEGER NOT NULL,\\n  order_id INTEGER NOT NULL,\\n  position INTEGER NOT NULL,\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000000000),\\n  item_minor INTEGER NOT NULL CHECK (item_minor >= 0),\\n  tax_minor INTEGER NOT NULL CHECK (tax_minor >= 0),\\n  PRIMARY KEY (refund_id, position),\\n  FOREIGN KEY (refund_id, order_id) REFERENCES refunds (id, order_id),\\n  FOREIGN KEY (order_id, position) REFERENCES order_lines (order_id, position)\\n) STRICT;\\n\\nCREATE INDEX idx_refund_lines_line ON refund_lines (order_id, position);\\n\\nCREATE TRIGGER refund_lines_within_line BEFORE INSERT ON refund_lines\\nWHEN EXISTS (\\n  SELECT 1 FROM order_lines l\\n  WHERE l.order_id = NEW.order_id AND l.position = NEW.position\\n    AND (\\n      l.quantity < NEW.quantity + COALESCE((SELECT SUM(x.quantity) FROM refund_lines x JOIN refunds r ON r.id = x.refund_id\\n        WHERE x.order_id = NEW.order_id AND x.position = NEW.position AND r.state IN ('pending', 'requires_action', 'succeeded')), 0)\\n      OR l.line_total_minor < NEW.item_minor + COALESCE((SELECT SUM(x.item_minor) FROM refund_lines x JOIN refunds r ON r.id = x.refund_id\\n        WHERE x.order_id = NEW.order_id AND x.position = NEW.position AND r.state IN ('pending', 'requires_action', 'succeeded')), 0)\\n      OR l.tax_minor < NEW.tax_minor + COALESCE((SELECT SUM(x.tax_minor) FROM refund_lines x JOIN refunds r ON r.id = x.refund_id\\n        WHERE x.order_id = NEW.order_id AND x.position = NEW.position AND r.state IN ('pending', 'requires_action', 'succeeded')), 0)\\n    )\\n)\\nBEGIN\\n  SELECT RAISE(ABORT, 'refund lines exceed what the order line sold');\\nEND;\\n\\nCREATE TRIGGER refund_lines_within_refund AFTER INSERT ON refund_lines\\nWHEN (SELECT SUM(item_minor) FROM refund_lines WHERE refund_id = NEW.refund_id) > (SELECT items_minor FROM refunds WHERE id = NEW.refund_id)\\n  OR (SELECT SUM(tax_minor) FROM refund_lines WHERE refund_id = NEW.refund_id) > (SELECT item_tax_minor FROM refunds WHERE id = NEW.refund_id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'refund lines exceed the refund');\\nEND;\\n\\nCREATE TRIGGER refund_lines_append_only BEFORE UPDATE ON refund_lines BEGIN SELECT RAISE(ABORT, 'refund lines are append-only'); END;\\nCREATE TRIGGER refund_lines_permanent BEFORE DELETE ON refund_lines BEGIN SELECT RAISE(ABORT, 'refund lines are permanent'); END;\\n\\nCREATE TABLE restocks (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  order_id INTEGER NOT NULL,\\n  position INTEGER NOT NULL,\\n  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000000000),\\n  reason TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 500),\\n  actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 200),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  FOREIGN KEY (order_id, position) REFERENCES order_lines (order_id, position)\\n) STRICT;\\n\\nCREATE INDEX idx_restocks_line ON restocks (order_id, position);\\n\\nCREATE TRIGGER restocks_within_returned BEFORE INSERT ON restocks\\nWHEN NEW.quantity + COALESCE((SELECT SUM(quantity) FROM restocks WHERE order_id = NEW.order_id AND position = NEW.position), 0)\\n  > COALESCE((SELECT returned FROM line_fulfillment WHERE order_id = NEW.order_id AND position = NEW.position), 0)\\nBEGIN\\n  SELECT RAISE(ABORT, 'restocks exceed the quantity returned');\\nEND;\\n\\nCREATE TRIGGER restocks_append_only BEFORE UPDATE ON restocks BEGIN SELECT RAISE(ABORT, 'restocks are append-only'); END;\\nCREATE TRIGGER restocks_permanent BEFORE DELETE ON restocks BEGIN SELECT RAISE(ABORT, 'restocks are permanent'); END;\\n\",\"checksum\":\"f15d00f71d2b759fbfb93227c292556bf5732beb8d0128298432d0a1fa9393f9\"},{\"version\":10,\"name\":\"0010_email_access.sql\",\"sql\":\"-- Transactional email and guest order access. A message row is created in the\\n-- transaction that records the change it reports, together with a durable\\n-- email_send work item. Bodies are rendered at send time from the order and\\n-- never stored. The access credential of a message is derived from a secret\\n-- that never enters the database; only its SHA-256 digest is stored here.\\n\\nCREATE TABLE email_messages (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  kind TEXT NOT NULL CHECK (kind IN ('order_confirmation', 'shipment', 'cancellation_voided', 'cancellation_items', 'refund', 'late_void', 'access_link')),\\n  order_id INTEGER REFERENCES orders (id),\\n  attempt_id INTEGER CHECK (attempt_id IS NULL OR attempt_id > 0),\\n  subject_id INTEGER NOT NULL DEFAULT 0 CHECK (subject_id >= 0),\\n  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation >= 1),\\n  state TEXT NOT NULL DEFAULT 'queued' CHECK (state IN ('queued', 'sending', 'sent', 'failed', 'unknown')),\\n  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),\\n  first_attempt_at INTEGER CHECK (first_attempt_at IS NULL OR first_attempt_at >= 0),\\n  last_attempt_at INTEGER CHECK (last_attempt_at IS NULL OR last_attempt_at >= 0),\\n  provider_id TEXT CHECK (provider_id IS NULL OR length(provider_id) BETWEEN 1 AND 255),\\n  last_error TEXT CHECK (last_error IS NULL OR length(last_error) <= 500),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= created_at),\\n  CHECK ((kind = 'late_void' AND attempt_id IS NOT NULL AND order_id IS NULL) OR (kind != 'late_void' AND attempt_id IS NULL AND order_id IS NOT NULL)),\\n  CHECK ((kind IN ('shipment', 'refund', 'cancellation_voided', 'cancellation_items') AND subject_id >= 1) OR (kind NOT IN ('shipment', 'refund', 'cancellation_voided', 'cancellation_items') AND subject_id = 0)),\\n  CHECK (state != 'sent' OR provider_id IS NOT NULL),\\n  CHECK (state = 'queued' OR attempts >= 1)\\n) STRICT;\\n\\nCREATE UNIQUE INDEX uq_email_messages_subject ON email_messages (kind, COALESCE(order_id, attempt_id), subject_id) WHERE kind != 'access_link';\\nCREATE INDEX idx_email_messages_order ON email_messages (order_id, id) WHERE order_id IS NOT NULL;\\n\\nCREATE TRIGGER email_messages_identity_immutable BEFORE UPDATE ON email_messages\\nWHEN NEW.id != OLD.id OR NEW.kind != OLD.kind OR NEW.order_id IS NOT OLD.order_id OR NEW.attempt_id IS NOT OLD.attempt_id\\n  OR NEW.subject_id != OLD.subject_id OR NEW.created_at != OLD.created_at\\nBEGIN\\n  SELECT RAISE(ABORT, 'an email message''s identity is immutable');\\nEND;\\n\\nCREATE TRIGGER email_messages_sent_is_final BEFORE UPDATE ON email_messages\\nWHEN OLD.state = 'sent' AND (NEW.state != 'sent' OR NEW.generation != OLD.generation OR NEW.provider_id IS NOT OLD.provider_id)\\nBEGIN\\n  SELECT RAISE(ABORT, 'a sent email message is final');\\nEND;\\n\\nCREATE TRIGGER email_messages_generation_grows BEFORE UPDATE OF generation ON email_messages\\nWHEN NEW.generation < OLD.generation\\nBEGIN\\n  SELECT RAISE(ABORT, 'an email message''s generation only grows');\\nEND;\\n\\nCREATE TRIGGER email_messages_permanent BEFORE DELETE ON email_messages BEGIN SELECT RAISE(ABORT, 'email messages are permanent'); END;\\n\\n-- One row per credential. The raw credential is 256 bits and appears only in\\n-- the email that carries it; each send generation of a message has its own.\\n-- A credential is valid until expires_at, 90 days after the first send\\n-- attempt that carried it, unless revoked_at is set.\\nCREATE TABLE order_access (\\n  digest BLOB PRIMARY KEY CHECK (length(digest) = 32),\\n  order_id INTEGER NOT NULL REFERENCES orders (id),\\n  message_id INTEGER NOT NULL REFERENCES email_messages (id),\\n  created_at INTEGER NOT NULL CHECK (created_at >= 0),\\n  expires_at INTEGER NOT NULL CHECK (expires_at > created_at),\\n  revoked_at INTEGER CHECK (revoked_at IS NULL OR revoked_at >= created_at)\\n) STRICT, WITHOUT ROWID;\\n\\nCREATE INDEX idx_order_access_order ON order_access (order_id);\\n\\nCREATE TRIGGER order_access_identity_immutable BEFORE UPDATE ON order_access\\nWHEN NEW.digest != OLD.digest OR NEW.order_id != OLD.order_id OR NEW.message_id != OLD.message_id OR NEW.created_at != OLD.created_at\\n  OR NEW.expires_at != OLD.expires_at OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NOT OLD.revoked_at)\\nBEGIN\\n  SELECT RAISE(ABORT, 'an order access credential can only be revoked');\\nEND;\\n\\nCREATE TRIGGER order_access_permanent BEFORE DELETE ON order_access BEGIN SELECT RAISE(ABORT, 'order access credentials are permanent'); END;\\n\\n-- Recovery requests per order number, kept for one hour by the program. A\\n-- request counts whether or not the number or the email matches, so the\\n-- limit and the answer reveal nothing.\\nCREATE TABLE order_lookups (\\n  id INTEGER PRIMARY KEY CHECK (id > 0),\\n  order_number INTEGER NOT NULL CHECK (order_number > 0),\\n  requested_at INTEGER NOT NULL CHECK (requested_at >= 0)\\n) STRICT;\\n\\nCREATE INDEX idx_order_lookups_number ON order_lookups (order_number, requested_at);\\nCREATE INDEX idx_order_lookups_time ON order_lookups (requested_at);\\n\",\"checksum\":\"6a3846a79d6626903455bd5d60483fe8dea1cbdfa40837cc7cd47044e589d922\"},{\"version\":11,\"name\":\"0011_shop_pages.sql\",\"sql\":\"-- Shop identity, information pages, and handle history. The shop name stays\\n-- in store(name); the rest of the identity is shop_profile. Information pages\\n-- are typed blocks stored as JSON text that the application decodes strictly.\\n-- A page's review mark names the page revision the merchant reviewed, so a\\n-- later edit makes the mark stale. Profile and pages feed the public catalog\\n-- snapshot, so writes to them advance catalog_state.generation. Review marks\\n-- and handle history do not need to, because the writes that change what the\\n-- public sees already do.\\n\\nCREATE TABLE shop_profile (\\n  id INTEGER PRIMARY KEY CHECK (id = 1),\\n  description TEXT NOT NULL CHECK (length(CAST(description AS BLOB)) <= 300),\\n  contact_email TEXT CHECK (contact_email IS NULL OR (length(contact_email) BETWEEN 3 AND 254 AND contact_email GLOB '*?@?*.?*' AND contact_email NOT GLOB '*[^!-~]*')),\\n  contact_phone TEXT CHECK (contact_phone IS NULL OR length(CAST(contact_phone AS BLOB)) BETWEEN 3 AND 40),\\n  revision INTEGER NOT NULL CHECK (revision >= 1),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= 0)\\n) STRICT;\\n\\nINSERT INTO shop_profile (id, description, contact_email, contact_phone, revision, updated_at) VALUES (1, '', NULL, NULL, 1, 0);\\n\\nCREATE TABLE shop_pages (\\n  kind TEXT PRIMARY KEY CHECK (kind IN ('about', 'shipping', 'returns', 'privacy', 'terms')),\\n  blocks TEXT NOT NULL CHECK (json_valid(blocks) AND json_type(blocks) = 'array' AND length(CAST(blocks AS BLOB)) <= 49152),\\n  revision INTEGER NOT NULL CHECK (revision >= 1),\\n  updated_at INTEGER NOT NULL CHECK (updated_at >= 0)\\n) STRICT;\\n\\nINSERT INTO shop_pages (kind, blocks, revision, updated_at) VALUES\\n  ('about', '[]', 1, 0), ('shipping', '[]', 1, 0), ('returns', '[]', 1, 0), ('privacy', '[]', 1, 0), ('terms', '[]', 1, 0);\\n\\nCREATE TABLE shop_page_reviews (\\n  kind TEXT PRIMARY KEY REFERENCES shop_pages (kind),\\n  reviewed_revision INTEGER NOT NULL CHECK (reviewed_revision >= 1),\\n  reviewed_by TEXT NOT NULL CHECK (length(reviewed_by) BETWEEN 1 AND 200),\\n  reviewed_at INTEGER NOT NULL CHECK (reviewed_at >= 0)\\n) STRICT;\\n\\nCREATE TABLE handle_redirects (\\n  kind TEXT NOT NULL CHECK (kind IN ('product', 'collection')),\\n  old_handle TEXT NOT NULL CHECK (length(old_handle) BETWEEN 1 AND 200),\\n  target_handle TEXT NOT NULL CHECK (length(target_handle) BETWEEN 1 AND 200 AND target_handle != old_handle),\\n  PRIMARY KEY (kind, old_handle)\\n) STRICT;\\n\\nCREATE INDEX handle_redirects_target ON handle_redirects (kind, target_handle);\\n\\nCREATE TRIGGER shop_profile_no_delete BEFORE DELETE ON shop_profile\\nBEGIN\\n  SELECT RAISE(ABORT, 'shop_profile is permanent');\\nEND;\\nCREATE TRIGGER shop_profile_update_advances_generation AFTER UPDATE ON shop_profile\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\n\\nCREATE TRIGGER shop_pages_no_delete BEFORE DELETE ON shop_pages\\nBEGIN\\n  SELECT RAISE(ABORT, 'shop_pages are permanent');\\nEND;\\nCREATE TRIGGER shop_pages_kind_immutable BEFORE UPDATE OF kind ON shop_pages\\nBEGIN\\n  SELECT RAISE(ABORT, 'a shop page kind never changes');\\nEND;\\nCREATE TRIGGER shop_pages_revision_monotonic BEFORE UPDATE ON shop_pages\\nWHEN NEW.revision < OLD.revision\\nBEGIN\\n  SELECT RAISE(ABORT, 'a shop page revision never decreases');\\nEND;\\nCREATE TRIGGER shop_pages_update_advances_generation AFTER UPDATE ON shop_pages\\nBEGIN\\n  UPDATE catalog_state SET generation = generation + 1 WHERE id = 1;\\nEND;\\n\\nCREATE TRIGGER products_insert_clears_redirect AFTER INSERT ON products\\nBEGIN\\n  DELETE FROM handle_redirects WHERE kind = 'product' AND old_handle = NEW.handle;\\nEND;\\nCREATE TRIGGER products_handle_redirect AFTER UPDATE OF handle ON products\\nWHEN NEW.handle != OLD.handle\\nBEGIN\\n  DELETE FROM handle_redirects WHERE kind = 'product' AND old_handle = NEW.handle;\\n  UPDATE handle_redirects SET target_handle = NEW.handle WHERE kind = 'product' AND target_handle = OLD.handle;\\n  INSERT OR REPLACE INTO handle_redirects (kind, old_handle, target_handle) VALUES ('product', OLD.handle, NEW.handle);\\nEND;\\nCREATE TRIGGER products_delete_clears_redirects AFTER DELETE ON products\\nBEGIN\\n  DELETE FROM handle_redirects WHERE kind = 'product' AND target_handle = OLD.handle;\\nEND;\\n\\nCREATE TRIGGER collections_insert_clears_redirect AFTER INSERT ON collections\\nBEGIN\\n  DELETE FROM handle_redirects WHERE kind = 'collection' AND old_handle = NEW.handle;\\nEND;\\nCREATE TRIGGER collections_handle_redirect AFTER UPDATE OF handle ON collections\\nWHEN NEW.handle != OLD.handle\\nBEGIN\\n  DELETE FROM handle_redirects WHERE kind = 'collection' AND old_handle = NEW.handle;\\n  UPDATE handle_redirects SET target_handle = NEW.handle WHERE kind = 'collection' AND target_handle = OLD.handle;\\n  INSERT OR REPLACE INTO handle_redirects (kind, old_handle, target_handle) VALUES ('collection', OLD.handle, NEW.handle);\\nEND;\\nCREATE TRIGGER collections_delete_clears_redirects AFTER DELETE ON collections\\nBEGIN\\n  DELETE FROM handle_redirects WHERE kind = 'collection' AND target_handle = OLD.handle;\\nEND;\\n\",\"checksum\":\"498c46e6717286d099a45d73235f6edae34a4ccef6b1617926bb9d127875cd6f\"}],\"originHost\":\"storied.localhost:64366\",\"shop\":{\"tenantId\":\"storied\",\"origin\":\"http://storied.localhost:64366\"},\"payments\":{\"mode\":\"test\",\"apiBase\":\"http://stripe-sim.localhost:64369\"},\"email\":{\"from\":\"storied <orders@storied.example>\",\"replyTo\":null,\"apiBase\":\"http://127.0.0.1:64368\"}}"));
